        ZmanMethod("sof-zman-tfila-mga72-minutes", "prayer", "Latest teffilah Magen Avraham 72 minutes \u00b7 Day: Dawn 72 minutes \u2192 Nightfall 72 minutes", false, false, false, true, true, explicitElevation = false, sourceMethod = "getSofZmanTfilaMGA72Minutes", hebrewLabel = "סוף זמן תפילה מגן אברהם 72 minutes", definition = "4 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Dawn 72 minutes → Nightfall 72 minutes", sourceDefinition = "This method returns the latest zman tfila (time to recite shema in the morning) that is 4 getShaahZmanis72Minutes() shaos zmaniyos (solar hours) after getAlos72Minutes(), according to the Magen Avraham (MGA) . The day is calculated from 72 minutes before getSunriseBasedOnElevationSetting() to 72 minutes after getSunsetBasedOnElevationSetting(). The use of elevation depends on the isUseElevation() setting).") { c -> c.getSofZmanTfilaMGA72Minutes() },
        ZmanMethod("mincha-gedola-gra", "mincha-gedolah", "Earliest Mincha Vilna Gaon \u00b7 Day: Sunrise (profile elevation policy) \u2192 Sunset (profile elevation policy)", false, false, false, true, true, explicitElevation = false, sourceMethod = "getMinchaGedolaGRA", hebrewLabel = "מנחה גדולה הגר״א", definition = "6.5 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Sunrise (profile elevation policy) → Sunset (profile elevation policy)", sourceDefinition = "This method returns the latest mincha gedola ,the earliest time one can pray mincha that is 6.5 shaos zmaniyos (solar hours) after sunrise or sea level sunrise (depending on the isUseElevation() setting), according to the GRA . Mincha gedola is the earliest time one can pray mincha . The Ramba\"m is of the opinion that it is better to delay mincha until mincha ketana GRA while the Ra\"sh, Tur, GRA and others are of the opinion that mincha can be prayed lechatchila starting at mincha gedola . The day is calculated from sea level sunrise to sea level sunset or sunrise to sunset (depending on the isUseElevation() setting). @todo Consider adjusting this to calculate the time as half an hour zmaniyos after getChatzosHayom() that uses isUseAstronomicalChatzos() to determine the type of chatzos to utilize (if the calculator support astronomical chatzos ), based on the isUseAstronomicalChatzos() setting.") { c -> c.getMinchaGedolaGRA() },
        ZmanMethod("mincha-ketana-gra", "mincha-ketanah", "Mincha ketanah Vilna Gaon \u00b7 Day: Sunrise (profile elevation policy) \u2192 Sunset (profile elevation policy)", false, false, false, true, true, explicitElevation = false, sourceMethod = "getMinchaKetanaGRA", hebrewLabel = "מנחה קטנה הגר״א", definition = "9.5 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Sunrise (profile elevation policy) → Sunset (profile elevation policy)", sourceDefinition = "This method returns mincha ketana ,the preferred earliest time to pray mincha in the opinion of the Rambam and others, that is 9.5 shaos zmaniyos (solar hours) after sunrise or sea level sunrise (depending on the isUseElevation() setting), according to the GRA . For more information on this see the documentation on mincha gedola . The day is calculated from sea level sunrise to sea level sunset or from sunrise to sunset (depending on the isUseElevation() setting.") { c -> c.getMinchaKetanaGRA() },
        ZmanMethod("plag-hamincha-gra", "plag", "Plag Vilna Gaon \u00b7 Day: Sunrise (profile elevation policy) \u2192 Sunset (profile elevation policy)", false, false, false, true, true, explicitElevation = false, sourceMethod = "getPlagHaminchaGRA", hebrewLabel = "פלג המנחה הגר״א", definition = "10.75 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Sunrise (profile elevation policy) → Sunset (profile elevation policy)", sourceDefinition = "This method returns plag hamincha , that is 10.75 shaos zmaniyos (solar hours) after sunrise or sea level sunrise (depending on the isUseElevation() setting), according to the GRA . Plag hamincha is the earliest time that Shabbos can be started. The day is calculated from sea level sunrise to sea level sunset or sunrise to sunset (depending on the isUseElevation()") { c -> c.getPlagHaminchaGRA() },
        ZmanMethod("shaah-zmanis-gra", "duration", "Temporal hour Vilna Gaon \u00b7 Day: Sunrise (profile elevation policy) \u2192 Sunset (profile elevation policy)", true, false, false, true, false, explicitElevation = false, sourceMethod = "getShaahZmanisGRA", hebrewLabel = "שעה זמנית הגר״א", definition = "One twelfth of the specified day interval; a duration rather than a clock time. Day: Sunrise (profile elevation policy) → Sunset (profile elevation policy)", sourceDefinition = "A method that returns a shaah zmanis (Instant) temporal hour) according to the opinion of the GRA . This calculation divides the day based on the opinion of the GRA that the day runs from sea level sunrise to sea level sunset or sunrise to sunset (depending on the isUseElevation() setting). The day is split into 12 equal parts with each one being a shaah zmanis . This method is similar to getTemporalHour(), but can account for elevation.") { c -> c.getShaahZmanisGRA() },
        ZmanMethod("shaah-zmanis72-minutes", "duration", "Temporal hour 72 minutes \u00b7 Day: Dawn 72 minutes \u2192 Nightfall 72 minutes", true, false, false, true, false, explicitElevation = false, sourceMethod = "getShaahZmanis72Minutes", hebrewLabel = "שעה זמנית 72 minutes", definition = "One twelfth of the specified day interval; a duration rather than a clock time. Day: Dawn 72 minutes → Nightfall 72 minutes", sourceDefinition = "A method that returns a shaah zmanis (temporal hour) according to the opinion of the Magen Avraham (MGA) based on a 72-minute alos and tzais . This calculation divides the day that runs from dawn to dusk (for sof zman krias shema and tfila ). Dawn for this calculation is 72 minutes before sunrise or sea level sunrise (depending on the isUseElevation() elevation setting) and dusk is 72 minutes after getSunset() sunset or sea level sunset (depending on the isUseElevation() elevation setting). This day is split into 12 equal parts with each part being a shaah zmanis . Alternate methods of calculating a shaah zmanis according to the Magen Avraham (MGA) are available in the subclass ComprehensiveZmanimCalendar.") { c -> c.getShaahZmanis72Minutes() },
        ZmanMethod("shaah-zmanis19-point8-degrees", "duration", "Temporal hour 19.8\u00b0 below horizon \u00b7 Day: Dawn 19.8\u00b0 below horizon \u2192 Nightfall 19.8\u00b0 below horizon", true, false, false, false, false, explicitElevation = false, sourceMethod = "getShaahZmanis19Point8Degrees", hebrewLabel = "שעה זמנית 19.8° below the horizon", definition = "One twelfth of the specified day interval; a duration rather than a clock time. Day: Dawn 19.8° below horizon → Nightfall 19.8° below horizon", sourceDefinition = "Method to return a shaah zmanis (temporal hour) calculated using a 19.8° dip. This calculation divides the day based on the opinion of the Magen Avraham (MGA) that the day runs from dawn to dusk. Dawn for this calculation is when the sun is 19.8° below the eastern geometric horizon before sunrise. Dusk for this is when the sun is 19.8° below the western geometric horizon after sunset. This day is split into 12 equal parts with each part being a shaah zmanis .") { c -> c.getShaahZmanis19Point8Degrees() },
        ZmanMethod("shaah-zmanis18-degrees", "duration", "Temporal hour 18\u00b0 below horizon \u00b7 Day: Dawn 18\u00b0 below horizon \u2192 Nightfall 18\u00b0 below horizon", true, false, false, false, false, explicitElevation = false, sourceMethod = "getShaahZmanis18Degrees", hebrewLabel = "שעה זמנית 18° below the horizon", definition = "One twelfth of the specified day interval; a duration rather than a clock time. Day: Dawn 18° below horizon → Nightfall 18° below horizon", sourceDefinition = "Method to return a shaah zmanis (temporal hour) calculated using a 18° dip. This calculation divides the day based on the opinion of the Magen Avraham (MGA) that the day runs from dawn to dusk. Dawn for this calculation is when the sun is 18° below the eastern geometric horizon before sunrise. Dusk for this is when the sun is 18° below the western geometric horizon after sunset. This day is split into 12 equal parts with each part being a shaah zmanis .") { c -> c.getShaahZmanis18Degrees() },
        ZmanMethod("shaah-zmanis26-degrees", "duration", "Temporal hour 26\u00b0 below horizon \u00b7 Day: Dawn 26\u00b0 below horizon \u2192 Nightfall 26\u00b0 below horizon", true, false, false, false, false, explicitElevation = false, sourceMethod = "getShaahZmanis26Degrees", hebrewLabel = "שעה זמנית 26° below the horizon", definition = "One twelfth of the specified day interval; a duration rather than a clock time. Day: Dawn 26° below horizon → Nightfall 26° below horizon", sourceDefinition = "Method to return a shaah zmanis (temporal hour) calculated using a dip of 26°. This calculation divides the day based on the opinion of the Magen Avraham (MGA) that the day runs from dawn to dusk. Dawn for this calculation is when the sun is 26° below the eastern geometric horizon before sunrise. Dusk for this is when the sun is 26° below the western geometric horizon after sunset. This day is split into 12 equal parts with each part being a shaah zmanis . Since zmanim that use this method are extremely late or early and at a point when the sky is a long time past the 18° point where the darkest point is reached, zmanim that use this should only be used lechumra , such as delaying the start of nighttime mitzvos .") { c -> c.getShaahZmanis26Degrees() },
        ZmanMethod("shaah-zmanis16-point1-degrees", "duration", "Temporal hour 16.1\u00b0 below horizon \u00b7 Day: Dawn 16.1\u00b0 below horizon \u2192 Nightfall 16.1\u00b0 below horizon", true, false, false, false, false, explicitElevation = false, sourceMethod = "getShaahZmanis16Point1Degrees", hebrewLabel = "שעה זמנית 16.1° below the horizon", definition = "One twelfth of the specified day interval; a duration rather than a clock time. Day: Dawn 16.1° below horizon → Nightfall 16.1° below horizon", sourceDefinition = "Method to return a shaah zmanis (temporal hour) calculated using a dip of 16.1°. This calculation divides the day based on the opinion that the day runs from dawn to dusk. Dawn for this calculation is when the sun is 16.1° below the eastern geometric horizon before sunrise and dusk is when the sun is 16.1° below the western geometric horizon after sunset. This day is split into 12 equal parts with each part being a shaah zmanis .") { c -> c.getShaahZmanis16Point1Degrees() },
        ZmanMethod("shaah-zmanis60-minutes", "duration", "Temporal hour 60 minutes \u00b7 Day: Dawn 60 minutes \u2192 Nightfall 60 minutes", true, false, false, true, false, explicitElevation = false, sourceMethod = "getShaahZmanis60Minutes", hebrewLabel = "שעה זמנית 60 minutes", definition = "One twelfth of the specified day interval; a duration rather than a clock time. Day: Dawn 60 minutes → Nightfall 60 minutes", sourceDefinition = "Method to return a shaah zmanis (solar hour) according to the opinion of the Magen Avraham (MGA) . This calculation divides the day based on the opinion of the MGA that the day runs from dawn to dusk. Dawn for this calculation is 60 minutes before sunrise and dusk is 60 minutes after sunset. This day is split into 12 equal parts with each part being a shaah zmanis . Alternate methods of calculating a shaah zmanis are available in the subclass ComprehensiveZmanimCalendar.") { c -> c.getShaahZmanis60Minutes() },
        ZmanMethod("shaah-zmanis72-minutes-zmanis", "duration", "Temporal hour 72 temporal minutes \u00b7 Day: Dawn 72 temporal minutes \u2192 Nightfall 72 temporal minutes", true, false, false, true, false, explicitElevation = false, sourceMethod = "getShaahZmanis72MinutesZmanis", hebrewLabel = "שעה זמנית 72 temporal minutes", definition = "One twelfth of the specified day interval; a duration rather than a clock time. Day: Dawn 72 temporal minutes → Nightfall 72 temporal minutes", sourceDefinition = "Method to return a shaah zmanis (temporal hour) according to the opinion of the Magen Avraham (MGA) based on alos being getAlos72Zmanis() 72 minutes zmaniyos before getSunrise() sunrise}. This calculation divides the day based on the opinion of the MGA that the day runs from dawn to dusk. Dawn for this calculation is 72 minutes zmaniyos before sunrise and dusk is 72 minutes zmaniyos after sunset. This day is split into 12 equal parts with each part being a shaah zmanis . This is identical to 1/10th of the day from getSunrise() to getSunset().") { c -> c.getShaahZmanis72MinutesZmanis() },
        ZmanMethod("shaah-zmanis90-minutes", "duration", "Temporal hour 90 minutes \u00b7 Day: Dawn 90 minutes \u2192 Nightfall 90 minutes", true, false, false, true, false, explicitElevation = false, sourceMethod = "getShaahZmanis90Minutes", hebrewLabel = "שעה זמנית 90 minutes", definition = "One twelfth of the specified day interval; a duration rather than a clock time. Day: Dawn 90 minutes → Nightfall 90 minutes", sourceDefinition = "Method to return a shaah zmanis (temporal hour) calculated using a dip of 90 minutes. This calculation divides the day based on the opinion of the Magen Avraham (MGA) that the day runs from dawn to dusk. Dawn for this calculation is 90 minutes before sunrise and dusk is 90 minutes after sunset. This day is split into 12 equal parts with each part being a shaah zmanis .") { c -> c.getShaahZmanis90Minutes() },
        ZmanMethod("shaah-zmanis90-minutes-zmanis", "duration", "Temporal hour 90 temporal minutes \u00b7 Day: Dawn 90 temporal minutes \u2192 Nightfall 90 temporal minutes", true, false, false, true, false, explicitElevation = false, sourceMethod = "getShaahZmanis90MinutesZmanis", hebrewLabel = "שעה זמנית 90 temporal minutes", definition = "One twelfth of the specified day interval; a duration rather than a clock time. Day: Dawn 90 temporal minutes → Nightfall 90 temporal minutes", sourceDefinition = "Method to return a shaah zmanis (temporal hour) according to the opinion of the Magen Avraham (MGA) based on alos being getAlos90Zmanis() 90 minutes zmaniyos before getSunrise(). This calculation divides the day based on the opinion of the MGA that the day runs from dawn to dusk. Dawn is calculated as 90 minutes zmaniyos before sunrise and dusk is 90 minutes zmaniyos after sunset. This day is split into 12 equal parts with each part being a shaah zmanis . This is 1/8th of the day from getSunrise() to sunset.") { c -> c.getShaahZmanis90MinutesZmanis() },
        ZmanMethod("shaah-zmanis96-minutes-zmanis", "duration", "Temporal hour 96 temporal minutes \u00b7 Day: Dawn 96 temporal minutes \u2192 Nightfall 96 temporal minutes", true, false, false, true, false, explicitElevation = false, sourceMethod = "getShaahZmanis96MinutesZmanis", hebrewLabel = "שעה זמנית 96 temporal minutes", definition = "One twelfth of the specified day interval; a duration rather than a clock time. Day: Dawn 96 temporal minutes → Nightfall 96 temporal minutes", sourceDefinition = "Method to return a shaah zmanis (temporal hour) according to the opinion of the Magen Avraham (MGA) based on alos being 96 minutes zmaniyos before getSunrise(). This calculation divides the day based on the opinion of the MGA that the day runs from dawn to dusk. Dawn is calculated as 96 minutes zmaniyos before sunrise and dusk is 96 minutes zmaniyos after sunset. This day is split into 12 equal parts with each part being a shaah zmanis . This is identical to 1/7.5th of the day from getSunrise() to sunset.") { c -> c.getShaahZmanis96MinutesZmanis() },
        ZmanMethod("shaah-zmanis-ateret-torah", "duration", "Temporal hour Ateret Torah \u00b7 Day: Dawn 72 temporal minutes \u2192 Nightfall Ateret Torah", true, true, false, true, false, explicitElevation = false, sourceMethod = "getShaahZmanisAteretTorah", hebrewLabel = "שעה זמנית עטרת תורה", definition = "One twelfth of the specified day interval; a duration rather than a clock time. Day: Dawn 72 temporal minutes → Nightfall Ateret Torah", sourceDefinition = "Method to return a shaah zmanis (temporal hour) according to the opinion of the Chacham Yosef Harari-Raful of Yeshivat Ateret Torah calculated with alos being 1/10th of sunrise to sunset day, or 72 minutes zmaniyos of such a day before getSunrise(), and tzais is usually calculated as getTzaisAteretTorah() 40 minutes (configurable to any offset via setAteretTorahSunsetOffset(double)) after getSunset() sunset. This day is split into 12 equal parts with each part being a shaah zmanis . Note that with this system, chatzos (midday) will not be the point that the sun is halfway across the sky.") { c -> c.getShaahZmanisAteretTorah() },
        ZmanMethod("shaah-zmanis-alos16-point1-degrees-to-tzais-geonim3-point8-degrees", "duration", "Temporal hour Dawn 16.1\u00b0 below horizon To Nightfall Geonim 3.8\u00b0 below horizon \u00b7 Day: Dawn 16.1\u00b0 below horizon \u2192 Nightfall Geonim 3.8\u00b0 below horizon", true, false, false, false, false, explicitElevation = false, sourceMethod = "getShaahZmanisAlos16Point1DegreesToTzaisGeonim3Point8Degrees", hebrewLabel = "שעה זמנית עלות השחר 16.1° below the horizon To צאת הכוכבים גאונים 3.8° below the horizon", definition = "One twelfth of the specified day interval; a duration rather than a clock time. Day: Dawn 16.1° below horizon → Nightfall Geonim 3.8° below horizon", sourceDefinition = "Method to return a shaah zmanis (temporal hour) used by some zmanim according to the opinion of Rabbi Yaakov Moshe Hillel as published in the luach of the Bais Horaah of Yeshivat Chevrat Ahavat Shalom that is based on a day starting 72 minutes before sunrise in degrees getAlos16Point1Degrees() alos 16.1° and ending 14 minutes after sunset in degrees getTzaisGeonim3Point8Degrees() tzais 3.8°. This day is split into 12 equal parts with each part being a shaah zmanis . Note that with this system, chatzos (midday) will not be the point that the sun is getSunTransit() halfway across the sky. These shaos zmaniyos are used for Mincha Ketana and Plag Hamincha . The 14 minutes are based on 3/4 of an 18 minute mil , with half a minute added for Rav Yosi's Bain Hashmashos . Sources for an asymmetrical day-based calculation can be seen in the documentation of getSofZmanShmaAlos16Point1DegreesToTzaisGeonim7Point083Degrees.") { c -> c.getShaahZmanisAlos16Point1DegreesToTzaisGeonim3Point8Degrees() },
        ZmanMethod("shaah-zmanis-alos16-point1-degrees-to-tzais-geonim3-point7-degrees", "duration", "Temporal hour Dawn 16.1\u00b0 below horizon To Nightfall Geonim 3.7\u00b0 below horizon \u00b7 Day: Dawn 16.1\u00b0 below horizon \u2192 Nightfall Geonim 3.7\u00b0 below horizon", true, false, false, false, false, explicitElevation = false, sourceMethod = "getShaahZmanisAlos16Point1DegreesToTzaisGeonim3Point7Degrees", hebrewLabel = "שעה זמנית עלות השחר 16.1° below the horizon To צאת הכוכבים גאונים 3.7° below the horizon", definition = "One twelfth of the specified day interval; a duration rather than a clock time. Day: Dawn 16.1° below horizon → Nightfall Geonim 3.7° below horizon", sourceDefinition = "Method to return a shaah zmanis (temporal hour) used by some zmanim according to the opinion of Rabbi Yaakov Moshe Hillel as published in the luach of the Bais Horaah of Yeshivat Chevrat Ahavat Shalom that is based on a day starting 72 minutes before sunrise in degrees getAlos16Point1Degrees() alos 16.1° and ending 13.5 minutes after sunset in degrees getTzaisGeonim3Point7Degrees() tzais 3.7°. This day is split into 12 equal parts with each part being a shaah zmanis . Note that with this system, chatzos (midday) will not be the point that the sun is getSunTransit() halfway across the sky. These shaos zmaniyos are used for Mincha Gedola calculation. Sources for an asymmetrical day-based calculation can be seen in the documentation of getSofZmanShmaAlos16Point1DegreesToTzaisGeonim7Point083Degrees.") { c -> c.getShaahZmanisAlos16Point1DegreesToTzaisGeonim3Point7Degrees() },
        ZmanMethod("shaah-zmanis-alos16-point1-degrees-to-tzais-geonim7-point083-degrees", "duration", "Temporal hour Dawn 16.1\u00b0 below horizon To Nightfall Geonim 7.083\u00b0 below horizon \u00b7 Day: Dawn 16.1\u00b0 below horizon \u2192 Nightfall Geonim 7.083\u00b0 below horizon", true, false, false, false, false, explicitElevation = false, sourceMethod = "getShaahZmanisAlos16Point1DegreesToTzaisGeonim7Point083Degrees", hebrewLabel = "שעה זמנית עלות השחר 16.1° below the horizon To צאת הכוכבים גאונים 7.083° below the horizon", definition = "One twelfth of the specified day interval; a duration rather than a clock time. Day: Dawn 16.1° below horizon → Nightfall Geonim 7.083° below horizon", sourceDefinition = "Method to return a shaah zmanis (temporal hour) used by some zmanim according to some opinions that is based on a day starting at alos 16.1° and ending getTzaisGeonim7Point083Degrees tzais 8.083°. This day is split into 12 equal parts with each part being a shaah zmanis . Note that with this system, chatzos (midday) will not be the point that the sun is getSunTransit() halfway across the sky. Sources for an asymmetrical day-based calculation can be seen in the documentation of getSofZmanShmaAlos16Point1DegreesToTzaisGeonim7Point083Degrees.") { c -> c.getShaahZmanisAlos16Point1DegreesToTzaisGeonim7Point083Degrees() },
        ZmanMethod("shaah-zmanis96-minutes", "duration", "Temporal hour 96 minutes \u00b7 Day: Dawn 96 minutes \u2192 Nightfall 96 minutes", true, false, false, true, false, explicitElevation = false, sourceMethod = "getShaahZmanis96Minutes", hebrewLabel = "שעה זמנית 96 minutes", definition = "One twelfth of the specified day interval; a duration rather than a clock time. Day: Dawn 96 minutes → Nightfall 96 minutes", sourceDefinition = "Method to return a shaah zmanis (temporal hour) calculated using a dip of 96 minutes. This calculation divides the day based on the opinion of the Magen Avraham (MGA) that the day runs from dawn to dusk. Dawn for this calculation is 96 minutes before sunrise and dusk is 96 minutes after sunset. This day is split into 12 equal parts with each part being a shaah zmanis .") { c -> c.getShaahZmanis96Minutes() },
        ZmanMethod("shaah-zmanis120-minutes", "duration", "Temporal hour 120 minutes \u00b7 Day: Dawn 120 minutes \u2192 Nightfall 120 minutes", true, false, false, true, false, explicitElevation = false, sourceMethod = "getShaahZmanis120Minutes", hebrewLabel = "שעה זמנית 120 minutes", definition = "One twelfth of the specified day interval; a duration rather than a clock time. Day: Dawn 120 minutes → Nightfall 120 minutes", sourceDefinition = "Method to return a shaah zmanis (temporal hour) calculated using a dip of 120 minutes. This calculation divides the day based on the opinion of the Magen Avraham (MGA) that the day runs from dawn to dusk. Dawn for this calculation is 120 minutes before sunrise and dusk is 120 minutes after sunset. This day is split into 12 equal parts with each part being a shaah zmanis . Since zmanim that use this method are extremely late or early and at a point when the sky is a long time past the 18° point where the darkest point is reached, zmanim that use this should only be used lechumra only, such as delaying the start of nighttime mitzvos .") { c -> c.getShaahZmanis120Minutes() },
        ZmanMethod("shaah-zmanis120-minutes-zmanis", "duration", "Temporal hour 120 temporal minutes \u00b7 Day: Dawn 120 temporal minutes \u2192 Nightfall 120 temporal minutes", true, false, false, true, false, explicitElevation = false, sourceMethod = "getShaahZmanis120MinutesZmanis", hebrewLabel = "שעה זמנית 120 temporal minutes", definition = "One twelfth of the specified day interval; a duration rather than a clock time. Day: Dawn 120 temporal minutes → Nightfall 120 temporal minutes", sourceDefinition = "Method to return a shaah zmanis (temporal hour) according to the opinion of the Magen Avraham (MGA) based on alos being getAlos120Zmanis() 120 minutes zmaniyos before getSunrise(). This calculation divides the day based on the opinion of the MGA that the day runs from dawn to dusk. Dawn for this calculation is 120 minutes zmaniyos before sunrise and dusk is 120 minutes zmaniyos after sunset. This day is split into 12 equal parts with each part being a shaah zmanis . This is identical to 1/6th of the day from getSunrise() to sunset. Since zmanim that use this method are extremely late or early and at a point when the sky is a long time past the 18° point where the darkest point is reached, zmanim that use this should only be used lechumra such as delaying the start of nighttime mitzvos .") { c -> c.getShaahZmanis120MinutesZmanis() },
        ZmanMethod("plag-hamincha120-minutes-zmanis", "plag", "Plag 120 temporal minutes \u00b7 Day: Dawn 120 temporal minutes \u2192 Nightfall 120 temporal minutes", false, false, false, true, true, explicitElevation = false, sourceMethod = "getPlagHamincha120MinutesZmanis", hebrewLabel = "פלג המנחה 120 temporal minutes", definition = "10.75 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Dawn 120 temporal minutes → Nightfall 120 temporal minutes", sourceDefinition = "This method should be used lechumra only and returns the time of plag hamincha based on sunrise being 120 minutes zmaniyos or 1/6th of the day before sunrise. This is calculated as 10.75 hours after getAlos120Zmanis() dawn. The formula used is 10.75 getShaahZmanis120MinutesZmanis() after getAlos120Zmanis() dawn. Since the zman based on an extremely early alos and a very late tzais , it should only be used lechumra .") { c -> c.getPlagHamincha120MinutesZmanis() },
        ZmanMethod("plag-hamincha120-minutes", "plag", "Plag 120 minutes \u00b7 Day: Dawn 120 minutes \u2192 Nightfall 120 minutes", false, false, false, true, true, explicitElevation = false, sourceMethod = "getPlagHamincha120Minutes", hebrewLabel = "פלג המנחה 120 minutes", definition = "10.75 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Dawn 120 minutes → Nightfall 120 minutes", sourceDefinition = "{@summary This method plag hamincha according to the Magen Avraham with the day starting at getAlos120Minutes(). It should be used lechumra only}. This is calculated as 10.75 getShaahZmanis120Minutes() after getAlos120Minutes(). Since the zman based on an extremely early alos and a very late tzais , it returns a very late time (often after shkiah and can result in chillul Shabbos etc.) and should only be used lechumra .") { c -> c.getPlagHamincha120Minutes() },
        ZmanMethod("alos60-minutes", "dawn", "Dawn 60 minutes", false, false, false, true, false, explicitElevation = false, sourceMethod = "getAlos60Minutes", hebrewLabel = "עלות השחר 60 minutes", definition = "60 fixed clock minutes before sunrise. Sunrise/sunset follow the profile elevation policy.", sourceDefinition = "Method to return alos (dawn) calculated as 60 minutes before getSunriseBasedOnElevationSetting() (depends on the isUseElevation() setting). This is the time to walk the distance of 4 mil at 15 minutes a mil. This seems to be the opinion of the Chavas Yair in the Mekor Chaim, Orach Chaim Ch. 90, though the Mekor Chaim in Ch. 58 and in the Chut Hashani Ch. 97 states that a person walks 3 and a 1/3 mil in an hour, or an 18-minute mil. Also see the Divrei Malkiel Vol. 4, Ch. 20, page 34 ) who mentions the 15 minute mil lechumra by baking matzos. Also see the Maharik Ch. 173 where the questioner quoting the Ra'avan is of the opinion that the time to walk a mil is 15 minutes (5 mil in a little over an hour). There are many who believe that there is a ta'us sofer (scribe's error) in the Ra'avan, and it should 4 mil in a little over an hour, or an 18-minute mil. Time based offset calculations are based on the opinions that the time of the neshef (time between dawn and sunrise) does not vary by the time of year or location but purely depends on the time it takes to walk the distance of 4 mil. getTzaisGeonim9Point75Degrees() is a related zman that is a degree-based calculation based on 60 minutes.") { c -> c.getAlos60Minutes() },
        ZmanMethod("alos72-zmanis", "dawn", "Dawn 72 temporal minutes", false, false, false, true, false, explicitElevation = false, sourceMethod = "getAlos72Zmanis", hebrewLabel = "עלות השחר 72 temporal minutes", definition = "72 temporal minutes (one sixtieth of the sunrise-to-sunset temporal hour) before sunrise. Sunrise/sunset follow the profile elevation policy.", sourceDefinition = "Method to return alos (dawn) calculated using 72 minutes zmaniyos or 1/10th of the day before sunrise. This is based on an 18-minute mil so the time for 4 mil is 72 minutes which is 1/10th of a day (12 60 = 720) based on the day being from getSeaLevelSunrise() to sea level sunset or getSunrise() to getSunset() (depending on the isUseElevation() setting). The actual calculation is getSunriseBasedOnElevationSetting() - (getShaahZmanisGRA() 1.2). This calculation is used in the calendars published by the Hisachdus Harabanim D'Artzos Habris Ve'Canada .") { c -> c.getAlos72Zmanis() },
        ZmanMethod("alos96-minutes", "dawn", "Dawn 96 minutes", false, false, false, true, false, explicitElevation = false, sourceMethod = "getAlos96Minutes", hebrewLabel = "עלות השחר 96 minutes", definition = "96 fixed clock minutes before sunrise. Sunrise/sunset follow the profile elevation policy.", sourceDefinition = "Method to return alos (dawn) calculated using 96 minutes before getSunriseBasedOnElevationSetting() (depends on the isUseElevation() setting) that is based on the time to walk the distance of 4 mil at 24 minutes a mil. Time based offset calculations for alos are based on the opinion that the time of the Neshef (time between dawn and sunrise) does not vary by the time of year or location but purely depends on the time it takes to walk the distance of 4 mil.") { c -> c.getAlos96Minutes() },
        ZmanMethod("alos90-zmanis", "dawn", "Dawn 90 temporal minutes", false, false, false, true, false, explicitElevation = false, sourceMethod = "getAlos90Zmanis", hebrewLabel = "עלות השחר 90 temporal minutes", definition = "90 temporal minutes (one sixtieth of the sunrise-to-sunset temporal hour) before sunrise. Sunrise/sunset follow the profile elevation policy.", sourceDefinition = "Method to return alos (dawn) calculated using 90 minutes zmaniyos or 1/8th of the day before getSunrise() or getSeaLevelSunrise() (depending on the isUseElevation() setting). This is based on a 22.5-minute mil so the time for 4 mil is 90 minutes which is 1/8th of a day (12 60) / 8 = 90. The actual calculation used is getSunriseBasedOnElevationSetting() - (getShaahZmanisGRA() 1.5).") { c -> c.getAlos90Zmanis() },
        ZmanMethod("alos96-zmanis", "dawn", "Dawn 96 temporal minutes", false, false, false, true, false, explicitElevation = false, sourceMethod = "getAlos96Zmanis", hebrewLabel = "עלות השחר 96 temporal minutes", definition = "96 temporal minutes (one sixtieth of the sunrise-to-sunset temporal hour) before sunrise. Sunrise/sunset follow the profile elevation policy.", sourceDefinition = "This method returns alos (dawn) calculated using 96 minutes zmaniyos or 1/7.5th of the day before getSunriseBasedOnElevationSetting() (depends on the isUseElevation() setting). This is based on a 24-minute mil so the time for 4 mil is 96 minutes which is 1/7.5th of a day (12 60 / 7.5 = 96). The day is calculated from getSunriseBasedOnElevationSetting() to to getSunsetBasedOnElevationSetting() (depends on the isUseElevation(). The actual calculation used is getSunriseBasedOnElevationSetting() - (getShaahZmanisGRA() 1.6).") { c -> c.getAlos96Zmanis() },
        ZmanMethod("alos90-minutes", "dawn", "Dawn 90 minutes", false, false, false, true, false, explicitElevation = false, sourceMethod = "getAlos90Minutes", hebrewLabel = "עלות השחר 90 minutes", definition = "90 fixed clock minutes before sunrise. Sunrise/sunset follow the profile elevation policy.", sourceDefinition = "Method to return alos (dawn) calculated using 90 minutes before getSunriseBasedOnElevationSetting() (depends on the isUseElevation() setting) based on the time to walk the distance of 4 mil at 22.5 minutes a mil. Time-based offset calculations for alos are based on the opinion that the time of the Neshef (time between dawn and sunrise) does not vary by the time of year or location but purely depends on the time it takes to walk the distance of 4 mil.") { c -> c.getAlos90Minutes() },
        ZmanMethod("alos120-minutes", "dawn", "Dawn 120 minutes", false, false, false, true, false, explicitElevation = false, sourceMethod = "getAlos120Minutes", hebrewLabel = "עלות השחר 120 minutes", definition = "120 fixed clock minutes before sunrise. Sunrise/sunset follow the profile elevation policy.", sourceDefinition = "This method should be used lechumra only and returns alos (dawn) calculated using 120 minutes before getSunriseBasedOnElevationSetting() (that depends on the isUseElevation() setting) based on the time to walk the distance of 5 mil ( Ula ) at 24 minutes a mil. Time based offset calculations for alos are based on the opinions that the time of the neshef (time between dawn and sunrise) does not vary by the time of year or location but purely depends on the time it takes to walk the distance of 5 mil ( Ula ). Since this time is extremely early, it should only be used lechumra , such as not eating after this time on a fast day, and not as the start time for mitzvos that can only be performed during the day.") { c -> c.getAlos120Minutes() },
        ZmanMethod("alos120-zmanis", "dawn", "Dawn 120 temporal minutes", false, false, false, true, false, explicitElevation = false, sourceMethod = "getAlos120Zmanis", hebrewLabel = "עלות השחר 120 temporal minutes", definition = "120 temporal minutes (one sixtieth of the sunrise-to-sunset temporal hour) before sunrise. Sunrise/sunset follow the profile elevation policy.", sourceDefinition = "This method should be used lechumra only and method returns alos (dawn) calculated using 120 minutes zmaniyos or 1/6th of the day before getSunriseBasedOnElevationSetting() (depends on the isUseElevation() setting). This is based on a 24-minute mil so the time for 5 mil is 120 minutes which is 1/6th of a day (12 60 / 6 = 120). The day is calculated from getSunriseBasedOnElevationSetting() to getSunsetBasedOnElevationSetting() (depends on the isUseElevation(). The actual calculation used is getSunset() - (getShaahZmanisGRA() 2). Since this time is extremely early, it should only be used lechumra , such as not eating after this time on a fast day, and not as the start time for mitzvos that can only be performed during the day.") { c -> c.getAlos120Zmanis() },
        ZmanMethod("alos26-degrees", "dawn", "Dawn 26\u00b0 below horizon", false, false, false, false, false, explicitElevation = false, sourceMethod = "getAlos26Degrees", hebrewLabel = "עלות השחר 26° below the horizon", definition = "Morning sun 26° below the geometric horizon. A solar angle, not a fixed-minute interval; the time may be unavailable at high latitudes.", sourceDefinition = "This method should be used lechumra only and returns alos (dawn) calculated when the sun is ZENITH_26_DEGREES 26° below the eastern geometric horizon before sunrise. This calculation is based on the same calculation of 120 minutes but uses a degree-based calculation instead of 120 exact minutes. This calculation is based on the position of the sun 120 minutes before sunrise in Jerusalem around the equinox / equilux , which calculates to 26° below GEOMETRIC_ZENITH. Since this time is extremely early, it should only be used lechumra only, such as not eating after this time on a fast day, and not as the start time for mitzvos that can only be performed during the day.") { c -> c.getAlos26Degrees() },
        ZmanMethod("alos18-degrees", "dawn", "Dawn 18\u00b0 below horizon", false, false, false, false, false, explicitElevation = false, sourceMethod = "getAlos18Degrees", hebrewLabel = "עלות השחר 18° below the horizon", definition = "Morning sun 18° below the geometric horizon. A solar angle, not a fixed-minute interval; the time may be unavailable at high latitudes.", sourceDefinition = "A method to return alos (dawn) calculated when the sun is 18° below the eastern geometric horizon before sunrise.") { c -> c.getAlos18Degrees() },
        ZmanMethod("alos19-degrees", "dawn", "Dawn 19\u00b0 below horizon", false, false, false, false, false, explicitElevation = false, sourceMethod = "getAlos19Degrees", hebrewLabel = "עלות השחר 19° below the horizon", definition = "Morning sun 19° below the geometric horizon. A solar angle, not a fixed-minute interval; the time may be unavailable at high latitudes.", sourceDefinition = "A method to return alos (dawn) calculated when the sun is 19° below the eastern geometric horizon before sunrise. This is the Rambam 's alos according to Rabbi Moshe Kosower's Maaglei Tzedek , page 88, Ayeles Hashachar Vol. I, page 12 , Yom Valayla Shel Torah, Ch. 34, p. 222 and Rabbi Yaakov Shakow's Luach Ikvei Hayom .") { c -> c.getAlos19Degrees() },
        ZmanMethod("alos19-point8-degrees", "dawn", "Dawn 19.8\u00b0 below horizon", false, false, false, false, false, explicitElevation = false, sourceMethod = "getAlos19Point8Degrees", hebrewLabel = "עלות השחר 19.8° below the horizon", definition = "Morning sun 19.8° below the geometric horizon. A solar angle, not a fixed-minute interval; the time may be unavailable at high latitudes.", sourceDefinition = "Method to return alos (dawn) calculated when the sun is 19.8° below the eastern geometric horizon before sunrise. This calculation is based on the same calculation of 90 minutes before sunrise, but uses a degree-based calculation instead of 90 exact minutes. This calculation is based on the position of the sun 90 minutes before sunrise in Jerusalem around the equinox / equilux , which calculates to 19.8° below GEOMETRIC_ZENITH.") { c -> c.getAlos19Point8Degrees() },
        ZmanMethod("misheyakir12-point85-degrees", "misheyakir", "Misheyakir 12.85\u00b0 below horizon", false, false, false, false, false, explicitElevation = false, sourceMethod = "getMisheyakir12Point85Degrees", hebrewLabel = "משיכיר 12.85° below the horizon", definition = "Morning sun 12.85° below the geometric horizon. A solar angle, not a fixed-minute interval; the time may be unavailable at high latitudes.", sourceDefinition = "This method returns misheyakir based on the position of the sun 12.85° below GEOMETRIC_ZENITH (90°). This is based on the position of the sun slightly later than 57 minutes before getSunrise() in Jerusalem around the equinox / equilux . This zman is mentioned for use bish'as hadchak in the Birur Halacha Tinyana and Tlisa'ah in Orach Chaim siman 18 as 12.85°. Actual calculations show it to be slightly more than 12.9°, but the Birur Halacha indicates that 12.85° is a slight chumra (on a bedieved time) VS the 12.9° that 57 minutes calculates as (a difference of about 14 seconds at the equinox/equilux in Jerusalem). The zman of 12.9° is also mentioned in the Piskei Tshuvos siman 18, page 190 (where a typo indicates that this is the degree equivalent to 60 minutes before sunrise, when in fact at that point the sun is about 13.5° below the horizon). The 57 minute based time is mentioned by the Minchas Yitzchak vol. 9, siman 9 as 15 minutes before alos hashachar (though he is not clear what location he refers to, and does not mention a degree-based conversion). The Kaf Hachaim vol.1 siman 18, no. 18 states that in Yerushalayim 60 fixed minutes are used year round. Calculations show that 60 fixed minutes in Yerushalayim ranges from 13.5° at the spring equinox to 11.5° at the summer solstice. 57-minute misheyakir range from 12.9° at the winter equinox to 11° at the summer solstice. Analysis of the difference between 12.85° and 12.9°, shows that the maximum difference occurs at the summer solstice. In Lakewood, NJ at a latitude of 40.096°, the maximum difference throughout the year is 23 seconds. In the winter where there is the greatest need for very early misheyakir times, the difference is in the 16 second range. Going north to Montreal at latitude 45.5°, the maximum is 29 seconds and is about 18 seconds in the winter. Moving farther north to the latitude of Vilnius at a latitude of 54.68°, things change. Firstly, around the summer solstice it will not reach that far below the horizon. On the dates that both can be calculated, the maximum difference can be pretty high on one or two days of the year (around Jul 8), with about a week having over a two minute difference between the two. Even at the latitude of Vilna, from Dec - March, the difference is about 22 seconds.") { c -> c.getMisheyakir12Point85Degrees() },
        ZmanMethod("misheyakir11-point5-degrees", "misheyakir", "Misheyakir 11.5\u00b0 below horizon", false, false, false, false, false, explicitElevation = false, sourceMethod = "getMisheyakir11Point5Degrees", hebrewLabel = "משיכיר 11.5° below the horizon", definition = "Morning sun 11.5° below the geometric horizon. A solar angle, not a fixed-minute interval; the time may be unavailable at high latitudes.", sourceDefinition = "This method returns misheyakir based on the position of the sun when it is 11.5° below GEOMETRIC_ZENITH (90°). This calculation is used for calculating misheyakir according to some opinions. This calculation is based on the position of the sun 52 minutes before getSunrise() in Jerusalem around the equinox / equilux , which calculates to 11.5° below GEOMETRIC_ZENITH. @todo recalculate.") { c -> c.getMisheyakir11Point5Degrees() },
        ZmanMethod("misheyakir11-degrees", "misheyakir", "Misheyakir 11\u00b0 below horizon", false, false, false, false, false, explicitElevation = false, sourceMethod = "getMisheyakir11Degrees", hebrewLabel = "משיכיר 11° below the horizon", definition = "Morning sun 11° below the geometric horizon. A solar angle, not a fixed-minute interval; the time may be unavailable at high latitudes.", sourceDefinition = "This method returns misheyakir based on the position of the sun when it is 11° below GEOMETRIC_ZENITH (90°). This calculation is used for calculating misheyakir according to some opinions. This calculation is based on the position of the sun 48 minutes before getSunrise() in Jerusalem around the equinox / equilux , which calculates to 11° below GEOMETRIC_ZENITH.") { c -> c.getMisheyakir11Degrees() },
        ZmanMethod("misheyakir10-point2-degrees", "misheyakir", "Misheyakir 10.2\u00b0 below horizon", false, false, false, false, false, explicitElevation = false, sourceMethod = "getMisheyakir10Point2Degrees", hebrewLabel = "משיכיר 10.2° below the horizon", definition = "Morning sun 10.2° below the geometric horizon. A solar angle, not a fixed-minute interval; the time may be unavailable at high latitudes.", sourceDefinition = "This method returns misheyakir based on the position of the sun when it is 10.2° below GEOMETRIC_ZENITH (90°). This calculation is used for calculating misheyakir according to some opinions. This calculation is based on the position of the sun 45 minutes before getSunrise() in Jerusalem around the equinox which calculates to 10.2° below GEOMETRIC_ZENITH.") { c -> c.getMisheyakir10Point2Degrees() },
        ZmanMethod("misheyakir7-point65-degrees", "misheyakir", "Misheyakir 7.65\u00b0 below horizon", false, false, false, false, false, explicitElevation = false, sourceMethod = "getMisheyakir7Point65Degrees", hebrewLabel = "משיכיר 7.65° below the horizon", definition = "Morning sun 7.65° below the geometric horizon. A solar angle, not a fixed-minute interval; the time may be unavailable at high latitudes.", sourceDefinition = "This method returns misheyakir based on the position of the sun when it is 7.65° below GEOMETRIC_ZENITH (90°). The degrees are based on a 35/36 minute zman around the equinox / equilux , when the neshef (twilight) is the shortest. This time is based on Rabbi Moshe Feinstein who writes in Ohr Hachaim Vol. 4, Ch. 6 that misheyakir in New York is 35-40 minutes before sunrise, something that is a drop less than 8°. Rabbi Yisroel Taplin in Zmanei Yisrael (page 117) notes that Rabbi Yaakov Kamenetsky stated that it is not less than 36 minutes before sunrise (maybe it is 40 minutes). Sefer Yisrael Vehazmanim (p. 7) quotes the Tamar Yifrach in the name of the Satmar Rov that one should be stringent not consider misheyakir before 36 minutes. This is also the accepted minhag in Lakewood that is used in the Yeshiva . This follows the opinion of Rabbi Shmuel Kamenetsky who provided the time of 35/36 minutes, but did not provide a degree-based time. Since this zman depends on the level of light, Rabbi Yaakov Shakow presented this degree-based calculations to Rabbi Shmuel Kamenetsky who agreed to them.") { c -> c.getMisheyakir7Point65Degrees() },
        ZmanMethod("misheyakir9-point5-degrees", "misheyakir", "Misheyakir 9.5\u00b0 below horizon", false, false, false, false, false, explicitElevation = false, sourceMethod = "getMisheyakir9Point5Degrees", hebrewLabel = "משיכיר 9.5° below the horizon", definition = "Morning sun 9.5° below the geometric horizon. A solar angle, not a fixed-minute interval; the time may be unavailable at high latitudes.", sourceDefinition = "This method returns misheyakir based on the position of the sun when it is 9.5° below GEOMETRIC_ZENITH (90°). This calculation is based on Rabbi Dovid Kronglass's Calculation of 45 minutes in Baltimore as mentioned in Divrei Chachamim No. 24 brought down by the Birur Halacha, Tinyana, Ch. 18 . This calculates to 9.5°. Also see Rabbi Yaakov Yitzchok Neiman in Kovetz Eitz Chaim Vol. 9, p. 202 that the Vya'an Yosef did not want to rely on times earlier than 45 minutes in New York. This zman is also used in the calendars published by Rabbi Hershel Edelstein. As mentioned in Yisroel Vehazmanim, Rabbi Edelstein who was given the 45 minute zman by Rabbi Bick. The calendars published by the Edot Hamizrach communities also use this zman . This also follows the opinion of Rabbi Shmuel Kamenetsky who provided the time of 36 and 45 minutes, but did not provide a degree-based time. Since this zman depends on the level of light, Rabbi Yaakov Shakow presented these degree-based times to Rabbi Shmuel Kamenetsky who agreed to them.") { c -> c.getMisheyakir9Point5Degrees() },
        ZmanMethod("sof-zman-shma-mga19-point8-degrees", "shema", "Latest Shema Magen Avraham 19.8\u00b0 below horizon \u00b7 Day: Dawn 19.8\u00b0 below horizon \u2192 Nightfall 19.8\u00b0 below horizon", false, false, false, false, true, explicitElevation = false, sourceMethod = "getSofZmanShmaMGA19Point8Degrees", hebrewLabel = "סוף זמן קריאת שמע מגן אברהם 19.8° below the horizon", definition = "3 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Dawn 19.8° below horizon → Nightfall 19.8° below horizon", sourceDefinition = "This method returns the latest zman krias shema (time to recite Shema in the morning) according to the opinion of the Magen Avraham (MGA) based on alos being 19.8° before getSunrise(). This time is 3 shaos zmaniyos (solar hours) after getAlos19Point8Degrees() dawn based on the opinion of the MGA that the day is calculated from dawn to nightfall with both being 19.8° below sunrise or sunset. This returns the time of 3 getShaahZmanis19Point8Degrees() after dawn.") { c -> c.getSofZmanShmaMGA19Point8Degrees() },
        ZmanMethod("sof-zman-shma-mga16-point1-degrees", "shema", "Latest Shema Magen Avraham 16.1\u00b0 below horizon \u00b7 Day: Dawn 16.1\u00b0 below horizon \u2192 Nightfall 16.1\u00b0 below horizon", false, false, false, false, true, explicitElevation = false, sourceMethod = "getSofZmanShmaMGA16Point1Degrees", hebrewLabel = "סוף זמן קריאת שמע מגן אברהם 16.1° below the horizon", definition = "3 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Dawn 16.1° below horizon → Nightfall 16.1° below horizon", sourceDefinition = "This method returns the latest zman krias shema (time to recite Shema in the morning) according to the opinion of the Magen Avraham (MGA) based on alos being getAlos16Point1Degrees() 16.1° before getSunrise(). This time is 3 getShaahZmanis16Point1Degrees() shaos zmaniyos (solar hours) after dawn based on the opinion of the MGA that the day is calculated from dawn to nightfall with both being 16.1° below sunrise or sunset. This returns the time of 3 getShaahZmanis16Point1Degrees() after dawn.") { c -> c.getSofZmanShmaMGA16Point1Degrees() },
        ZmanMethod("sof-zman-shma-mga18-degrees", "shema", "Latest Shema Magen Avraham 18\u00b0 below horizon \u00b7 Day: Dawn 18\u00b0 below horizon \u2192 Nightfall 18\u00b0 below horizon", false, false, false, false, true, explicitElevation = false, sourceMethod = "getSofZmanShmaMGA18Degrees", hebrewLabel = "סוף זמן קריאת שמע מגן אברהם 18° below the horizon", definition = "3 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Dawn 18° below horizon → Nightfall 18° below horizon", sourceDefinition = "This method returns the latest zman krias shema (time to recite Shema in the morning) according to the opinion of the Magen Avraham (MGA) based on alos being 18° before getSunrise(). This time is 3 shaos zmaniyos (solar hours) after dawn based on the opinion of the MGA that the day is calculated from dawn to nightfall with both being 18° below sunrise or sunset. This returns the time of 3 getShaahZmanis18Degrees() after dawn.") { c -> c.getSofZmanShmaMGA18Degrees() },
        ZmanMethod("sof-zman-shma-mga72-minutes-zmanis", "shema", "Latest Shema Magen Avraham 72 temporal minutes \u00b7 Day: Dawn 72 temporal minutes \u2192 Nightfall 72 temporal minutes", false, false, false, true, true, explicitElevation = false, sourceMethod = "getSofZmanShmaMGA72MinutesZmanis", hebrewLabel = "סוף זמן קריאת שמע מגן אברהם 72 temporal minutes", definition = "3 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Dawn 72 temporal minutes → Nightfall 72 temporal minutes", sourceDefinition = "This method returns the latest zman krias shema (time to recite Shema in the morning) according to the opinion of the Magen Avraham (MGA) based on alos being 72 minutes zmaniyos , or 1/10th of the day before getSunrise(). This time is 3 shaos zmaniyos (solar hours) after dawn based on the opinion of the MGA that the day is calculated from a dawn of 72 minutes zmaniyos , or 1/10th of the day before sea level sunrise to nightfall of 72 minutes zmaniyos after sea level sunset. This returns the time of 3 getShaahZmanis72MinutesZmanis() after dawn.") { c -> c.getSofZmanShmaMGA72MinutesZmanis() },
        ZmanMethod("sof-zman-shma-mga90-minutes", "shema", "Latest Shema Magen Avraham 90 minutes \u00b7 Day: Dawn 90 minutes \u2192 Nightfall 90 minutes", false, false, false, true, true, explicitElevation = false, sourceMethod = "getSofZmanShmaMGA90Minutes", hebrewLabel = "סוף זמן קריאת שמע מגן אברהם 90 minutes", definition = "3 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Dawn 90 minutes → Nightfall 90 minutes", sourceDefinition = "This method returns the latest zman krias shema (time to recite Shema in the morning) according to the opinion of the Magen Avraham (MGA) based on alos being 90 minutes before getSunrise(). This time is 3 shaos zmaniyos (solar hours) after dawn based on the opinion of the MGA that the day is calculated from a dawn of 90 minutes before sunrise to nightfall of 90 minutes after sunset. This returns the time of 3 getShaahZmanis90Minutes() after dawn.") { c -> c.getSofZmanShmaMGA90Minutes() },
        ZmanMethod("sof-zman-shma-mga90-minutes-zmanis", "shema", "Latest Shema Magen Avraham 90 temporal minutes \u00b7 Day: Dawn 90 temporal minutes \u2192 Nightfall 90 temporal minutes", false, false, false, true, true, explicitElevation = false, sourceMethod = "getSofZmanShmaMGA90MinutesZmanis", hebrewLabel = "סוף זמן קריאת שמע מגן אברהם 90 temporal minutes", definition = "3 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Dawn 90 temporal minutes → Nightfall 90 temporal minutes", sourceDefinition = "This method returns the latest zman krias shema (time to recite Shema in the morning) according to the opinion of the Magen Avraham (MGA) based on alos being 90 minutes zmaniyos before sunrise. This time is 3 shaos zmaniyos (solar hours) after dawn based on the opinion of the MGA that the day is calculated from a getAlos90Zmanis() dawn of 90 minutes zmaniyos before sunrise to nightfall of 90 minutes zmaniyos after sunset. This returns the time of 3 getShaahZmanis90MinutesZmanis() after dawn.") { c -> c.getSofZmanShmaMGA90MinutesZmanis() },
        ZmanMethod("sof-zman-shma-mga96-minutes", "shema", "Latest Shema Magen Avraham 96 minutes \u00b7 Day: Dawn 96 minutes \u2192 Nightfall 96 minutes", false, false, false, true, true, explicitElevation = false, sourceMethod = "getSofZmanShmaMGA96Minutes", hebrewLabel = "סוף זמן קריאת שמע מגן אברהם 96 minutes", definition = "3 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Dawn 96 minutes → Nightfall 96 minutes", sourceDefinition = "This method returns the latest zman krias shema (time to recite Shema in the morning) according to the opinion of the Magen Avraham (MGA) based on alos being getAlos96Minutes() 96 minutes before getSunrise(). This time is 3 getShaahZmanis96Minutes() shaos zmaniyos (solar hours) after dawn based on the opinion of the MGA that the day is calculated from a dawn of 96 minutes before sunrise to getTzais96Minutes() nightfall of 96 minutes after sunset. This returns the time of 3 getShaahZmanis96Minutes() after dawn.") { c -> c.getSofZmanShmaMGA96Minutes() },
        ZmanMethod("sof-zman-shma-mga96-minutes-zmanis", "shema", "Latest Shema Magen Avraham 96 temporal minutes \u00b7 Day: Dawn 96 temporal minutes \u2192 Nightfall 96 temporal minutes", false, false, false, true, true, explicitElevation = false, sourceMethod = "getSofZmanShmaMGA96MinutesZmanis", hebrewLabel = "סוף זמן קריאת שמע מגן אברהם 96 temporal minutes", definition = "3 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Dawn 96 temporal minutes → Nightfall 96 temporal minutes", sourceDefinition = "This method returns the latest zman krias shema (time to recite Shema in the morning) according to the opinion of the Magen Avraham (MGA) based on alos being getAlos90Zmanis() 96 minutes zmaniyos before getSunrise(). This time is 3 getShaahZmanis96MinutesZmanis() shaos zmaniyos (solar hours) after dawn based on the opinion of the MGA that the day is calculated from a dawn of 96 minutes zmaniyos before sunrise to nightfall of 96 minutes zmaniyos after sunset. This returns the time of 3 getShaahZmanis96MinutesZmanis() after dawn.") { c -> c.getSofZmanShmaMGA96MinutesZmanis() },
        ZmanMethod("sof-zman-shma3-hours-before-chatzos", "shema", "Latest Shema 3 hours Before Chatzos \u00b7 Day: Sea Level Sunrise \u2192 Sea Level Sunset", false, false, false, false, false, explicitElevation = false, sourceMethod = "getSofZmanShma3HoursBeforeChatzos", hebrewLabel = "סוף זמן קריאת שמע 3 hours Before Chatzos", definition = "Three fixed clock hours before the profile’s chatzos. These are regular 60-minute hours, not temporal hours.", sourceDefinition = "This method returns the latest zman krias shema (time to recite Shema in the morning) calculated as 3 hours (regular clock hours and not shaos zmaniyos ) before getChatzosHayom(). Generally known as part of the \"Komarno\" zmanim after Rav Yitzchak Eizik of Komarno , a proponent of this calculation, it actually predates him a lot. It is the opinion of the Shach in the Nekudas Hakesef (Yoreh Deah 184), Rav Moshe Lifshitz in his commentary Lechem Mishneh on Brachos 1:2 . It is next brought down about 100 years later by the Yaavetz (in his siddur , Mor Uktziah Orach Chaim 1 , Lechem Shamayim, Brachos 1:2 and She'elos Yaavetz vol. 1 no. 40 ), Rav Yitzchak Eizik of Komarno in the Ma'aseh Oreg on Mishnayos Brachos 11:2, Shevus Yaakov, Chasan Sofer and others. See Yisrael Vehazmanim vol. 1 7:3, page 55 - 62 .") { c -> c.getSofZmanShma3HoursBeforeChatzos() },
        ZmanMethod("sof-zman-shma-mga120-minutes", "shema", "Latest Shema Magen Avraham 120 minutes \u00b7 Day: Dawn 120 minutes \u2192 Nightfall 120 minutes", false, false, false, true, true, explicitElevation = false, sourceMethod = "getSofZmanShmaMGA120Minutes", hebrewLabel = "סוף זמן קריאת שמע מגן אברהם 120 minutes", definition = "3 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Dawn 120 minutes → Nightfall 120 minutes", sourceDefinition = "This method returns the latest zman krias shema (time to recite Shema in the morning) according to the opinion of the Magen Avraham (MGA) based on alos being getAlos120Minutes() 120 minutes or 1/6th of the day before getSunrise(). This time is 3 getShaahZmanis120Minutes() shaos zmaniyos (solar hours) after dawn based on the opinion of the MGA that the day is calculated from a dawn of 120 minutes before sunrise to getTzais120Minutes() nightfall of 120 minutes after sunset. This returns the time of 3 getShaahZmanis120Minutes() after dawn. This is an extremely early zman that is very much a chumra .") { c -> c.getSofZmanShmaMGA120Minutes() },
        ZmanMethod("sof-zman-shma-alos16-point1-to-sunset", "shema", "Latest Shema Dawn 16.1To Sunset \u00b7 Day: Dawn 16.1\u00b0 below horizon \u2192 Sunset (profile elevation policy)", false, false, false, true, false, explicitElevation = false, sourceMethod = "getSofZmanShmaAlos16Point1ToSunset", hebrewLabel = "סוף זמן קריאת שמע עלות השחר 16.1To שקיעה", definition = "3 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. Day: Dawn 16.1° below horizon → Sunset (profile elevation policy)", sourceDefinition = "This method returns the latest zman krias shema (time to recite Shema in the morning) based on the opinion that the day starts at alos 16.1° and ends at getSeaLevelSunset() sea level sunset. This is the opinion of the חידושי וכללות הרז״ה in סימן ב׳ סע״ג וסע״ד and סי׳ ז׳ סע״ב and the מנורה הטהורה as mentioned by ישראל והזמנים ח״א סי׳ ז׳ פ״ג או׳ ט״ז . Also see אשר לשלמה, מועד, סי׳ ה׳ . Three shaos zmaniyos are calculated based on this day and added to alos to reach this time. This time is 3 shaos zmaniyos (solar hours) after getAlos16Point1Degrees() based on the opinion that the day is calculated from alos 16.1° to getSeaLevelSunset(). Note: Based on this calculation chatzos will not be at midday and isUseAstronomicalChatzosForOtherZmanim() will be ignored. Sources for an asymmetrical day-based calculation can be seen in the documentation of getSofZmanShmaAlos16Point1DegreesToTzaisGeonim7Point083Degrees.") { c -> c.getSofZmanShmaAlos16Point1ToSunset() },
        ZmanMethod("sof-zman-shma-alos16-point1-degrees-to-tzais-geonim7-point083-degrees", "shema", "Latest Shema Dawn 16.1\u00b0 below horizon To Nightfall Geonim 7.083\u00b0 below horizon \u00b7 Day: Dawn 16.1\u00b0 below horizon \u2192 Nightfall Geonim 7.083\u00b0 below horizon", false, false, false, false, false, explicitElevation = false, sourceMethod = "getSofZmanShmaAlos16Point1DegreesToTzaisGeonim7Point083Degrees", hebrewLabel = "סוף זמן קריאת שמע עלות השחר 16.1° below the horizon To צאת הכוכבים גאונים 7.083° below the horizon", definition = "3 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. Day: Dawn 16.1° below horizon → Nightfall Geonim 7.083° below horizon", sourceDefinition = "This method returns the latest zman krias shema (time to recite Shema in the morning) based on the opinion that the day is an asymmetrical day that starts at alos 16.1° and ends at getTzaisGeonim7Point083Degrees() tzais 7.083°. 3 shaos zmaniyos (temporal hours) are calculated based on this day and added to alos to reach this time. Sefer Yisroel Vehazmanim V. III in the explanation of zman no. 22 on page 1015 attributes the origin of this zman to Rabbi Yaakov al-Faraji's שו״ת מהרי״ף (who discusses zmanim in various places including chapters 6, 46, 47 and 49), Rabbi Yehosef Schwarz in the דברי יוסף in the name of Rabbi Nosson Adler , the Ben Ish Chai in שנה א׳ פ׳ ויקהל , Rabbi Nissim Kaduri Chazan's מעשה נסים (in the calendar at the end), Rabbi Matzliach Mazuz's שו״ת איש מצליח, in Dr. Baruch (Berthold) Cohn's luach Tabellen enthaltend die Zeitangaben für den Beginn der Nacht und des Tages für die Breitengrade + 66 bis -38 , שו״ת תשובות והנהגות ח״א no. 55 and 307 ( lechumra in the name of the מהרי״ל דיסקין and others) who calculate shaos zmaniyos based on an asymmetrical day from an early alos to an early tzais Note: Based on this calculation chatzos will not be at midday and isUseAstronomicalChatzosForOtherZmanim() will be ignored. There are many variations of this type of zman, with varying start and end times. The Yisroel Vehazmanim gave this as a relatively common one. Variations using this library are very simple. For example to calculate sof zman krias shema starting the day at the Rambam's alos of 18° and ending it at 3.7°, use the following code. {@snippet lang='java' : Instant sofZmanKS = czc.getSofZmanShma(czc.getAlos18Degrees(), czc.getTzaisGeonim3Point7Degrees(), false); }") { c -> c.getSofZmanShmaAlos16Point1DegreesToTzaisGeonim7Point083Degrees() },
        ZmanMethod("sof-zman-tfila-mga19-point8-degrees", "prayer", "Latest teffilah Magen Avraham 19.8\u00b0 below horizon \u00b7 Day: Dawn 19.8\u00b0 below horizon \u2192 Nightfall 19.8\u00b0 below horizon", false, false, false, false, true, explicitElevation = false, sourceMethod = "getSofZmanTfilaMGA19Point8Degrees", hebrewLabel = "סוף זמן תפילה מגן אברהם 19.8° below the horizon", definition = "4 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Dawn 19.8° below horizon → Nightfall 19.8° below horizon", sourceDefinition = "This method returns the latest zman tfila (time to recite the morning prayers) according to the opinion of the Magen Avraham (MGA) based on alos being getAlos19Point8Degrees() 19.8° before getSunrise(). This time is 4 getShaahZmanis19Point8Degrees() after getAlos19Point8Degrees() based on the opinion that the day is calculated from dawn to nightfall with both being 19.8° below sunrise or sunset.") { c -> c.getSofZmanTfilaMGA19Point8Degrees() },
        ZmanMethod("sof-zman-tfila-mga16-point1-degrees", "prayer", "Latest teffilah Magen Avraham 16.1\u00b0 below horizon \u00b7 Day: Dawn 16.1\u00b0 below horizon \u2192 Nightfall 16.1\u00b0 below horizon", false, false, false, false, true, explicitElevation = false, sourceMethod = "getSofZmanTfilaMGA16Point1Degrees", hebrewLabel = "סוף זמן תפילה מגן אברהם 16.1° below the horizon", definition = "4 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Dawn 16.1° below horizon → Nightfall 16.1° below horizon", sourceDefinition = "This method returns the latest zman tfila (time to recite the morning prayers) according to the opinion of the Magen Avraham (MGA) based on alos being getAlos16Point1Degrees() 16.1° before getSunrise(). This time is 4 getShaahZmanis16Point1Degrees() after getAlos16Point1Degrees() based on the opinion that the day is calculated from dawn to nightfall with both being 16.1° below sunrise or sunset.") { c -> c.getSofZmanTfilaMGA16Point1Degrees() },
        ZmanMethod("sof-zman-tfila-mga18-degrees", "prayer", "Latest teffilah Magen Avraham 18\u00b0 below horizon \u00b7 Day: Dawn 18\u00b0 below horizon \u2192 Nightfall 18\u00b0 below horizon", false, false, false, false, true, explicitElevation = false, sourceMethod = "getSofZmanTfilaMGA18Degrees", hebrewLabel = "סוף זמן תפילה מגן אברהם 18° below the horizon", definition = "4 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Dawn 18° below horizon → Nightfall 18° below horizon", sourceDefinition = "This method returns the latest zman tfila (time to recite the morning prayers) according to the opinion of the Magen Avraham (MGA) based on alos being getAlos18Degrees() before getSunrise(). This time is 4 getShaahZmanis18Degrees() after getAlos18Degrees() dawn based on the opinion that the day is calculated from dawn to nightfall with both being 18° below sunrise and sunset.") { c -> c.getSofZmanTfilaMGA18Degrees() },
        ZmanMethod("sof-zman-tfila-mga72-minutes-zmanis", "prayer", "Latest teffilah Magen Avraham 72 temporal minutes \u00b7 Day: Dawn 72 temporal minutes \u2192 Nightfall 72 temporal minutes", false, false, false, true, true, explicitElevation = false, sourceMethod = "getSofZmanTfilaMGA72MinutesZmanis", hebrewLabel = "סוף זמן תפילה מגן אברהם 72 temporal minutes", definition = "4 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Dawn 72 temporal minutes → Nightfall 72 temporal minutes", sourceDefinition = "This method returns the latest zman tfila (time to the morning prayers) according to the opinion of the Magen Avraham (MGA) based on alos being getAlos72Zmanis() 72 minutes zmaniyos or a 10th of the day before getSunrise(). This time is 4 getShaahZmanis72MinutesZmanis() after getAlos72Zmanis() based on the opinion that the day is calculated from a getAlos72Zmanis() before sunrise to getTzais72Zmanis() of 72 minutes zmaniyos after sunset.") { c -> c.getSofZmanTfilaMGA72MinutesZmanis() },
        ZmanMethod("sof-zman-tfila-mga90-minutes", "prayer", "Latest teffilah Magen Avraham 90 minutes \u00b7 Day: Dawn 90 minutes \u2192 Nightfall 90 minutes", false, false, false, true, true, explicitElevation = false, sourceMethod = "getSofZmanTfilaMGA90Minutes", hebrewLabel = "סוף זמן תפילה מגן אברהם 90 minutes", definition = "4 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Dawn 90 minutes → Nightfall 90 minutes", sourceDefinition = "This method returns the latest zman tfila (time to recite the morning prayers) according to the opinion of the Magen Avraham (MGA) based on alos being getAlos90Minutes() minutes before getSunrise(). This time is 4 getShaahZmanis90Minutes() after getAlos90Minutes() based on the opinion that the day is calculated from a getAlos90Minutes() before sunrise to getTzais90Minutes() after sunset.") { c -> c.getSofZmanTfilaMGA90Minutes() },
        ZmanMethod("sof-zman-tfila-mga90-minutes-zmanis", "prayer", "Latest teffilah Magen Avraham 90 temporal minutes \u00b7 Day: Dawn 90 temporal minutes \u2192 Nightfall 90 temporal minutes", false, false, false, true, true, explicitElevation = false, sourceMethod = "getSofZmanTfilaMGA90MinutesZmanis", hebrewLabel = "סוף זמן תפילה מגן אברהם 90 temporal minutes", definition = "4 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Dawn 90 temporal minutes → Nightfall 90 temporal minutes", sourceDefinition = "This method returns the latest zman tfila (time to the morning prayers) according to the opinion of the Magen Avraham (MGA) based on alos being getAlos90Zmanis() 90 minutes zmaniyos or 1/8th of the day before getSunrise(). This time is 4 getShaahZmanis90MinutesZmanis() after getAlos90Zmanis() based on the opinion that the day is calculated from a getAlos90Zmanis() to getTzais90Zmanis().") { c -> c.getSofZmanTfilaMGA90MinutesZmanis() },
        ZmanMethod("sof-zman-tfila-mga96-minutes", "prayer", "Latest teffilah Magen Avraham 96 minutes \u00b7 Day: Dawn 96 minutes \u2192 Nightfall 96 minutes", false, false, false, true, true, explicitElevation = false, sourceMethod = "getSofZmanTfilaMGA96Minutes", hebrewLabel = "סוף זמן תפילה מגן אברהם 96 minutes", definition = "4 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Dawn 96 minutes → Nightfall 96 minutes", sourceDefinition = "This method returns the latest zman tfila (time to recite the morning prayers) according to the opinion of the Magen Avraham (MGA) based on alos being getAlos96Minutes() minutes before getSunrise(). This time is 4 shaos zmaniyos (solar hours) after dawn based on the opinion of the MGA that the day is calculated from a dawn of 96 minutes before sunrise to nightfall of 96 minutes after sunset. This returns the time of 4 getShaahZmanis96Minutes() after dawn.") { c -> c.getSofZmanTfilaMGA96Minutes() },
        ZmanMethod("sof-zman-tfila-mga96-minutes-zmanis", "prayer", "Latest teffilah Magen Avraham 96 temporal minutes \u00b7 Day: Dawn 96 temporal minutes \u2192 Nightfall 96 temporal minutes", false, false, false, true, true, explicitElevation = false, sourceMethod = "getSofZmanTfilaMGA96MinutesZmanis", hebrewLabel = "סוף זמן תפילה מגן אברהם 96 temporal minutes", definition = "4 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Dawn 96 temporal minutes → Nightfall 96 temporal minutes", sourceDefinition = "This method returns the latest zman tfila (time to the morning prayers) according to the opinion of the Magen Avraham (MGA) based on alos being getAlos96Zmanis() 96 minutes zmaniyos before getSunrise(). This time is 4 getShaahZmanis96MinutesZmanis() after getAlos96Zmanis() based on the opinion that the day is calculated from a getAlos96Zmanis() before sunrise to getTzais96Zmanis() after sunset. This returns the time of 4 getShaahZmanis96MinutesZmanis() after getAlos96Zmanis().") { c -> c.getSofZmanTfilaMGA96MinutesZmanis() },
        ZmanMethod("sof-zman-tfila-mga120-minutes", "prayer", "Latest teffilah Magen Avraham 120 minutes \u00b7 Day: Dawn 120 minutes \u2192 Nightfall 120 minutes", false, false, false, true, true, explicitElevation = false, sourceMethod = "getSofZmanTfilaMGA120Minutes", hebrewLabel = "סוף זמן תפילה מגן אברהם 120 minutes", definition = "4 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Dawn 120 minutes → Nightfall 120 minutes", sourceDefinition = "This method returns the latest zman tfila (time to recite the morning prayers) according to the opinion of the Magen Avraham (MGA) based on alos being getAlos120Minutes() before getSunrise() . This time is 4 getShaahZmanis120Minutes() after getAlos120Minutes() based on the opinion that the day is calculated from a getAlos120Minutes(), 120 minutes before sunrise to getTzais120Minutes(), 120 minutes after sunset. This is an extremely early zman that is very stringent chumra .") { c -> c.getSofZmanTfilaMGA120Minutes() },
        ZmanMethod("sof-zman-tfila2-hours-before-chatzos", "prayer", "Latest teffilah 2 hours Before Chatzos \u00b7 Day: Sea Level Sunrise \u2192 Sea Level Sunset", false, false, false, false, false, explicitElevation = false, sourceMethod = "getSofZmanTfila2HoursBeforeChatzos", hebrewLabel = "סוף זמן תפילה 2 hours Before Chatzos", definition = "Two fixed clock hours before the profile’s chatzos. These are regular 60-minute hours, not temporal hours.", sourceDefinition = "This method returns the latest zman tfila (time to recite the morning prayers) calculated as 2 hours before getChatzosHayom(). This is based on the opinions that calculate sof zman krias shema as getSofZmanShma3HoursBeforeChatzos(). This returns the time of 2 hours before getChatzosHayom().") { c -> c.getSofZmanTfila2HoursBeforeChatzos() },
        ZmanMethod("mincha-gedola30-minutes", "mincha-gedolah", "Earliest Mincha 30 minutes \u00b7 Day: Sea Level Sunrise \u2192 Sea Level Sunset", false, false, false, false, false, explicitElevation = false, sourceMethod = "getMinchaGedola30Minutes", hebrewLabel = "מנחה גדולה 30 minutes", definition = "Thirty fixed clock minutes after the profile’s chatzos; not half a temporal hour.", sourceDefinition = "This method returns mincha gedola calculated as 30 minutes after chatzos and not 1/2 of a shaah zmanis after chatzos as calculated by getMinchaGedola. Some use this time to delay the start of mincha in the winter when 1/2 of a shaah zmanis is less than 30 minutes. See getMinchaGedolaGreaterThan30(Instant) for a convenience method that returns the later of the 2 calculations. One should not use this time to start mincha before the standard mincha gedola . See Shulchan Aruch Orach Chayim 234:1 and the Shaar Hatziyon seif katan ches . Since this calculation is a fixed 30 minutes of regular clock time after chatzos , even if isUseAstronomicalChatzosForOtherZmanim() is false, this mincha gedola time will be affected by isUseAstronomicalChatzos() and not by isUseAstronomicalChatzosForOtherZmanim().") { c -> c.getMinchaGedola30Minutes() },
        ZmanMethod("mincha-gedola72-minutes", "mincha-gedolah", "Earliest Mincha 72 minutes \u00b7 Day: Dawn 72 minutes \u2192 Nightfall 72 minutes", false, false, false, true, true, explicitElevation = false, sourceMethod = "getMinchaGedola72Minutes", hebrewLabel = "מנחה גדולה 72 minutes", definition = "6.5 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Dawn 72 minutes → Nightfall 72 minutes", sourceDefinition = "This method returns the time of mincha gedola according to the Magen Avraham with the day starting 72 minutes before sunrise and ending 72 minutes after sunset. This is the earliest time to pray mincha . For more information on this see the documentation on mincha gedola . This is calculated as 6.5 solar hours after alos . The calculation used is 6.5 getShaahZmanis72Minutes() after alos . If isUseAstronomicalChatzosForOtherZmanim() is set to true, the calculation will be based on 0.5 Instant) half-day based sha'ah zmanis between getChatzosHayom() and getTzais72Minutes() after getChatzosHayom().") { c -> c.getMinchaGedola72Minutes() },
        ZmanMethod("mincha-gedola16-point1-degrees", "mincha-gedolah", "Earliest Mincha 16.1\u00b0 below horizon \u00b7 Day: Dawn 16.1\u00b0 below horizon \u2192 Nightfall 16.1\u00b0 below horizon", false, false, false, false, true, explicitElevation = false, sourceMethod = "getMinchaGedola16Point1Degrees", hebrewLabel = "מנחה גדולה 16.1° below the horizon", definition = "6.5 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Dawn 16.1° below horizon → Nightfall 16.1° below horizon", sourceDefinition = "This method returns the time of mincha gedola according to the Magen Avraham with the day starting and ending 16.1° below the horizon. This is the earliest time to pray mincha . For more information on mincha gedola , see getMinchaGedolaGRA(). This is calculated as 6.5 getShaahZmanis16Point1Degrees() after alos . If isUseAstronomicalChatzosForOtherZmanim() is set to true, the calculation will be based on 0.5 getHalfDayBasedShaahZmanis(Instant, Instant) half-day based sha'ah zmanis between getChatzosHayom() and getAlos16Point1Degrees() after getChatzosHayom().") { c -> c.getMinchaGedola16Point1Degrees() },
        ZmanMethod("mincha-gedola-ahavat-shalom", "mincha-gedolah", "Earliest Mincha Ahavat Shalom \u00b7 Day: Sea Level Sunrise \u2192 Sea Level Sunset", false, false, false, false, false, explicitElevation = false, sourceMethod = "getMinchaGedolaAhavatShalom", hebrewLabel = "מנחה גדולה אהבת שלום", definition = "The later of thirty fixed minutes after chatzos and half a temporal hour after chatzos. This temporal hour is one twelfth of dawn at 16.1° below the horizon to nightfall at 3.7°. The profile half-day switch does not change this formula.", sourceDefinition = "This method returns the time of mincha gedola based on the opinion of Rabbi Yaakov Moshe Hillel as published in the luach of the Bais Horaah of Yeshivat Chevrat Ahavat Shalom that mincha gedola is calculated as half a shaah zmanis after chatzos with shaos zmaniyos calculated based on a day starting at getAlos16Point1Degrees() and ending at getTzaisGeonim3Point7Degrees(). The later of this time or 30 clock minutes after chatzos is returned. See getMinchaGedolaGreaterThan30(Instant) for a way to calculate the later of 30 minutes or this mincha gedola . For more information about mincha gedola see the documentation on mincha gedola . Since calculation of this zman involves chatzos that is offset from the center of the astronomical day, isUseAstronomicalChatzosForOtherZmanim() is N/A here. Sources for an asymmetrical day-based calculation can be seen in the documentation of getSofZmanShmaAlos16Point1DegreesToTzaisGeonim7Point083Degrees.") { c -> c.getMinchaGedolaAhavatShalom() },
        ZmanMethod("mincha-gedola-gragreater-than30", "mincha-gedolah", "Earliest Mincha Vilna Gaon Later than 30 \u00b7 Day: Sunrise (profile elevation policy) \u2192 Sunset (profile elevation policy)", false, false, false, true, true, explicitElevation = false, sourceMethod = "getMinchaGedolaGRAGreaterThan30", hebrewLabel = "מנחה גדולה הגר״א Later than 30", definition = "The later of the GRA mincha gedolah result and thirty fixed clock minutes after the profile’s chatzos.", sourceDefinition = "This is a convenience method that returns the later of getMinchaGedolaGRA() and getMinchaGedola30Minutes(). In the winter when 1/2 of a shaah zmanis is less than 30 minutes getMinchaGedola30Minutes() will be returned, otherwise getMinchaGedolaGRA() will be returned. Since this calculation can be an offset of chatzos (if 30 clock minutes > 1/2 of a shaah zmanis ), even if isUseAstronomicalChatzosForOtherZmanim() is false, this mincha time may be affected by isUseAstronomicalChatzos().") { c -> c.getMinchaGedolaGRAGreaterThan30() },
        ZmanMethod("mincha-ketana16-point1-degrees", "mincha-ketanah", "Mincha ketanah 16.1\u00b0 below horizon \u00b7 Day: Dawn 16.1\u00b0 below horizon \u2192 Nightfall 16.1\u00b0 below horizon", false, false, false, false, true, explicitElevation = false, sourceMethod = "getMinchaKetana16Point1Degrees", hebrewLabel = "מנחה קטנה 16.1° below the horizon", definition = "9.5 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Dawn 16.1° below horizon → Nightfall 16.1° below horizon", sourceDefinition = "This method returns the time of mincha ketana according to the Magen Avraham with the day starting and ending 16.1° below the horizon. This is the preferred earliest time to pray mincha according to the opinion of the Rambam and others. For more information on mincha ketana see the documentation on getMinchaGedolaGRA(). This is calculated as 9.5 getShaahZmanis16Point1Degrees() after getAlos16Point1Degrees().") { c -> c.getMinchaKetana16Point1Degrees() },
        ZmanMethod("mincha-ketana-ahavat-shalom", "mincha-ketanah", "Mincha ketanah Ahavat Shalom \u00b7 Day: Dawn 16.1\u00b0 below horizon \u2192 Nightfall Geonim 3.8\u00b0 below horizon", false, false, false, false, false, explicitElevation = false, sourceMethod = "getMinchaKetanaAhavatShalom", hebrewLabel = "מנחה קטנה אהבת שלום", definition = "Two and a half temporal hours before nightfall at 3.8° below the horizon; the temporal hour is one twelfth of dawn at 16.1° to that nightfall.", sourceDefinition = "This method returns the time of mincha ketana based on the opinion of Rabbi Yaakov Moshe Hillel as published in the luach of the Bais Horaah of Yeshivat Chevrat Ahavat Shalom that mincha ketana is calculated as 2.5 shaos zmaniyos before getTzaisGeonim3Point8Degrees() with shaos zmaniyos calculated based on a day starting at getAlos16Point1Degrees() and ending at getTzaisGeonim3Point8Degrees(). Mincha ketana is the preferred earliest time to pray mincha according to the opinion of the Rambam and others. For more information on mincha ketana see the documentation on getMinchaKetanaGRA().") { c -> c.getMinchaKetanaAhavatShalom() },
        ZmanMethod("mincha-ketana72-minutes", "mincha-ketanah", "Mincha ketanah 72 minutes \u00b7 Day: Dawn 72 minutes \u2192 Nightfall 72 minutes", false, false, false, true, true, explicitElevation = false, sourceMethod = "getMinchaKetana72Minutes", hebrewLabel = "מנחה קטנה 72 minutes", definition = "9.5 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Dawn 72 minutes → Nightfall 72 minutes", sourceDefinition = "This method returns the time of mincha ketana according to the Magen Avraham with the day starting 72 minutes before sunrise and ending 72 minutes after sunset. This is the preferred earliest time to pray mincha according to the opinion of the Rambam and others. For more information on this see the documentation on getMinchaGedolaGRA(). This is calculated as 9.5 getShaahZmanis72Minutes() after alos .") { c -> c.getMinchaKetana72Minutes() },
        ZmanMethod("plag-hamincha60-minutes", "plag", "Plag 60 minutes \u00b7 Day: Dawn 60 minutes \u2192 Nightfall 60 minutes", false, false, false, true, true, explicitElevation = false, sourceMethod = "getPlagHamincha60Minutes", hebrewLabel = "פלג המנחה 60 minutes", definition = "10.75 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Dawn 60 minutes → Nightfall 60 minutes", sourceDefinition = "This method returns the time of plag hamincha according to the Magen Avraham with the day starting 60 minutes before sunrise and ending 60 minutes after sunset. This is calculated as 10.75 getShaahZmanis60Minutes() after getAlos60Minutes().") { c -> c.getPlagHamincha60Minutes() },
        ZmanMethod("plag-hamincha72-minutes", "plag", "Plag 72 minutes \u00b7 Day: Dawn 72 minutes \u2192 Nightfall 72 minutes", false, false, false, true, true, explicitElevation = false, sourceMethod = "getPlagHamincha72Minutes", hebrewLabel = "פלג המנחה 72 minutes", definition = "10.75 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Dawn 72 minutes → Nightfall 72 minutes", sourceDefinition = "This method should be used lechumra only and returns the time of plag hamincha according to the Magen Avraham with the day starting 72 minutes before sunrise and ending 72 minutes after sunset. This is calculated as 10.75 getShaahZmanis72Minutes() after getAlos72Minutes(). Since plag by this calculation can occur after sunset, it should only be used lechumra .") { c -> c.getPlagHamincha72Minutes() },
        ZmanMethod("plag-hamincha90-minutes", "plag", "Plag 90 minutes \u00b7 Day: Dawn 90 minutes \u2192 Nightfall 90 minutes", false, false, false, true, true, explicitElevation = false, sourceMethod = "getPlagHamincha90Minutes", hebrewLabel = "פלג המנחה 90 minutes", definition = "10.75 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Dawn 90 minutes → Nightfall 90 minutes", sourceDefinition = "This method should be used lechumra only and returns the time of plag hamincha according to the Magen Avraham with the day starting 90 minutes before sunrise and ending 90 minutes after sunset. This is calculated as 10.75 getShaahZmanis90Minutes() after getAlos90Minutes(). Since plag by this calculation can occur after sunset, it should only be used lechumra .") { c -> c.getPlagHamincha90Minutes() },
        ZmanMethod("plag-hamincha96-minutes", "plag", "Plag 96 minutes \u00b7 Day: Dawn 96 minutes \u2192 Nightfall 96 minutes", false, false, false, true, true, explicitElevation = false, sourceMethod = "getPlagHamincha96Minutes", hebrewLabel = "פלג המנחה 96 minutes", definition = "10.75 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Dawn 96 minutes → Nightfall 96 minutes", sourceDefinition = "This method should be used lechumra only and returns the time of plag hamincha according to the Magen Avraham with the day starting 96 minutes before sunrise and ending 96 minutes after sunset. This is calculated as 10.75 getShaahZmanis96Minutes() after getAlos96Minutes(). Since plag by this calculation can occur after shkiah , it should only be used lechumra .") { c -> c.getPlagHamincha96Minutes() },
        ZmanMethod("plag-hamincha96-minutes-zmanis", "plag", "Plag 96 temporal minutes \u00b7 Day: Dawn 96 temporal minutes \u2192 Nightfall 96 temporal minutes", false, false, false, true, true, explicitElevation = false, sourceMethod = "getPlagHamincha96MinutesZmanis", hebrewLabel = "פלג המנחה 96 temporal minutes", definition = "10.75 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Dawn 96 temporal minutes → Nightfall 96 temporal minutes", sourceDefinition = "This method should be used lechumra only and returns the time of plag hamincha . This is calculated as 10.75 getAlos96Zmanis() after dawn. Since plag by this calculation can occur after shkiah ), it should only be used lechumra .") { c -> c.getPlagHamincha96MinutesZmanis() },
        ZmanMethod("plag-hamincha90-minutes-zmanis", "plag", "Plag 90 temporal minutes \u00b7 Day: Dawn 90 temporal minutes \u2192 Nightfall 90 temporal minutes", false, false, false, true, true, explicitElevation = false, sourceMethod = "getPlagHamincha90MinutesZmanis", hebrewLabel = "פלג המנחה 90 temporal minutes", definition = "10.75 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Dawn 90 temporal minutes → Nightfall 90 temporal minutes", sourceDefinition = "This method should be used lechumra only and returns the time of plag hamincha . This is calculated as 10.75 hours after dawn. The formula used is 10.75 getShaahZmanis90MinutesZmanis() after dawn. Since plag by this calculation can occur after sunset, it should only be used lechumra .") { c -> c.getPlagHamincha90MinutesZmanis() },
        ZmanMethod("plag-hamincha72-minutes-zmanis", "plag", "Plag 72 temporal minutes \u00b7 Day: Dawn 72 temporal minutes \u2192 Nightfall 72 temporal minutes", false, false, false, true, true, explicitElevation = false, sourceMethod = "getPlagHamincha72MinutesZmanis", hebrewLabel = "פלג המנחה 72 temporal minutes", definition = "10.75 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Dawn 72 temporal minutes → Nightfall 72 temporal minutes", sourceDefinition = "This method should be used lechumra only and returns the time of plag hamincha . This is calculated as 10.75 hours after getAlos72Zmanis(). The formula used is 10.75 getShaahZmanis72MinutesZmanis() after dawn. Since plag by this calculation can occur after sunset, it should only be used lechumra .") { c -> c.getPlagHamincha72MinutesZmanis() },
        ZmanMethod("plag-hamincha16-point1-degrees", "plag", "Plag 16.1\u00b0 below horizon \u00b7 Day: Dawn 16.1\u00b0 below horizon \u2192 Nightfall 16.1\u00b0 below horizon", false, false, false, false, true, explicitElevation = false, sourceMethod = "getPlagHamincha16Point1Degrees", hebrewLabel = "פלג המנחה 16.1° below the horizon", definition = "10.75 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Dawn 16.1° below horizon → Nightfall 16.1° below horizon", sourceDefinition = "This method should be used lechumra only and returns the time of plag hamincha based on the opinion that the day starts at getAlos16Point1Degrees() and ends at getTzais16Point1Degrees(). This is calculated as 10.75 getShaahZmanis16Point1Degrees() after getAlos16Point1Degrees(). Since plag by this calculation can occur after shkiah , it should only be used lechumra .") { c -> c.getPlagHamincha16Point1Degrees() },
        ZmanMethod("plag-hamincha19-point8-degrees", "plag", "Plag 19.8\u00b0 below horizon \u00b7 Day: Dawn 19.8\u00b0 below horizon \u2192 Nightfall 19.8\u00b0 below horizon", false, false, false, false, true, explicitElevation = false, sourceMethod = "getPlagHamincha19Point8Degrees", hebrewLabel = "פלג המנחה 19.8° below the horizon", definition = "10.75 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Dawn 19.8° below horizon → Nightfall 19.8° below horizon", sourceDefinition = "This method should be used lechumra only and returns the time of plag hamincha based on the opinion that the day starts at getAlos19Point8Degrees() and ends at getTzais19Point8Degrees(). This is calculated as 10.75 getShaahZmanis19Point8Degrees() after dawn. Since plag by this calculation can occur after shkiah , it should only be used lechumra .") { c -> c.getPlagHamincha19Point8Degrees() },
        ZmanMethod("plag-hamincha26-degrees", "plag", "Plag 26\u00b0 below horizon \u00b7 Day: Dawn 26\u00b0 below horizon \u2192 Nightfall 26\u00b0 below horizon", false, false, false, false, true, explicitElevation = false, sourceMethod = "getPlagHamincha26Degrees", hebrewLabel = "פלג המנחה 26° below the horizon", definition = "10.75 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Dawn 26° below horizon → Nightfall 26° below horizon", sourceDefinition = "This method should be used lechumra only and returns the time of plag hamincha based on the opinion that the day starts at getAlos26Degrees() and ends at getTzais26Degrees(). This is calculated as 10.75 getShaahZmanis26Degrees() after getAlos26Degrees(). Since the zman based on an extremely early alos and a very late tzais , it should only be used lechumra .") { c -> c.getPlagHamincha26Degrees() },
        ZmanMethod("plag-hamincha18-degrees", "plag", "Plag 18\u00b0 below horizon \u00b7 Day: Dawn 18\u00b0 below horizon \u2192 Nightfall 18\u00b0 below horizon", false, false, false, false, true, explicitElevation = false, sourceMethod = "getPlagHamincha18Degrees", hebrewLabel = "פלג המנחה 18° below the horizon", definition = "10.75 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Dawn 18° below horizon → Nightfall 18° below horizon", sourceDefinition = "This method should be used lechumra only and returns the time of plag hamincha based on the opinion that the day starts at getAlos18Degrees() and ends at getTzais18Degrees(). This is calculated as 10.75 getShaahZmanis18Degrees() after getAlos18Degrees(). Since plag by this calculation can occur after sunset, it should only be used lechumra .") { c -> c.getPlagHamincha18Degrees() },
        ZmanMethod("plag-alos-to-sunset", "plag", "Plag Dawn To Sunset \u00b7 Day: Dawn 16.1\u00b0 below horizon \u2192 Sunset (profile elevation policy)", false, false, false, true, false, explicitElevation = false, sourceMethod = "getPlagAlosToSunset", hebrewLabel = "פלג המנחה עלות השחר To שקיעה", definition = "10.75 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. Day: Dawn 16.1° below horizon → Sunset (profile elevation policy)", sourceDefinition = "This method should be used lechumra only and returns the time of plag hamincha based on the opinion that the day starts at getAlos16Point1Degrees() and ends at getSunsetBasedOnElevationSetting. This time is 10.75 shaos zmaniyos after getAlos16Point1Degrees(). Since plag by this calculation can occur after shkiah , it should only be used lechumra .") { c -> c.getPlagAlosToSunset() },
        ZmanMethod("plag-alos16-point1-degrees-to-tzais-geonim7-point083-degrees", "plag", "Plag Dawn 16.1\u00b0 below horizon To Nightfall Geonim 7.083\u00b0 below horizon \u00b7 Day: Dawn 16.1\u00b0 below horizon \u2192 Nightfall Geonim 7.083\u00b0 below horizon", false, false, false, false, false, explicitElevation = false, sourceMethod = "getPlagAlos16Point1DegreesToTzaisGeonim7Point083Degrees", hebrewLabel = "פלג המנחה עלות השחר 16.1° below the horizon To צאת הכוכבים גאונים 7.083° below the horizon", definition = "10.75 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. Day: Dawn 16.1° below horizon → Nightfall Geonim 7.083° below horizon", sourceDefinition = "This method returns the time of plag hamincha based on the opinion that the day starts at getAlos16Point1Degrees() and ends at getTzaisGeonim7Point083Degrees(). The time is 10.75 getShaahZmanisAlos16Point1DegreesToTzaisGeonim7Point083Degrees() after getAlos16Point1Degrees() to reach this time. Sources for an asymmetrical day-based calculation can be seen in the documentation of getSofZmanShmaAlos16Point1DegreesToTzaisGeonim7Point083Degrees.") { c -> c.getPlagAlos16Point1DegreesToTzaisGeonim7Point083Degrees() },
        ZmanMethod("plag-ahavat-shalom", "plag", "Plag Ahavat Shalom \u00b7 Day: Dawn 16.1\u00b0 below horizon \u2192 Nightfall Geonim 3.8\u00b0 below horizon", false, false, false, false, false, explicitElevation = false, sourceMethod = "getPlagAhavatShalom", hebrewLabel = "פלג המנחה אהבת שלום", definition = "One and a quarter temporal hours before nightfall at 3.8° below the horizon; the temporal hour is one twelfth of dawn at 16.1° to that nightfall.", sourceDefinition = "This method returns the time of plag hamincha (the earliest time that Shabbos can be started) based on the opinion of Rabbi Yaakov Moshe Hillel as published in the luach of the Bais Horaah of Yeshivat Chevrat Ahavat Shalom that that plag hamincha is calculated as 1.25 getShaahZmanisAlos16Point1DegreesToTzaisGeonim3Point8Degrees before getTzaisGeonim3Point8Degrees(). Sources for an asymmetrical day-based calculation can be seen in the documentation of getSofZmanShmaAlos16Point1DegreesToTzaisGeonim7Point083Degrees.") { c -> c.getPlagAhavatShalom() },
        ZmanMethod("bain-hashmashos-rt13-point24-degrees", "twilight", "Twilight Rabbeinu Tam 13.24\u00b0 below horizon", false, false, false, false, false, explicitElevation = false, sourceMethod = "getBainHashmashosRT13Point24Degrees", hebrewLabel = "בין השמשות רבנו תם 13.24° below the horizon", definition = "Evening sun 13.24° below the geometric horizon. A solar angle, not a fixed-minute interval; the time may be unavailable at high latitudes.", sourceDefinition = "Method to return the beginning of bain hashmashos of Rabbeinu Tam calculated when the sun is 13.24° below the western geometric horizon (90°) after sunset. This calculation is based on the same calculation of bain hashmashos Rabbeinu Tam 58.5 minutes but uses a degree-based calculation instead of 58.5 exact minutes. This calculation is based on the position of the sun 58.5 minutes after sunset in Jerusalem around the equinox / equilux , which calculates to 13.24° below GEOMETRIC_ZENITH. NOTE: As per Yisrael Vehazmanim Vol. III page 1025, No. 50, a dip of slightly less than 13° should be used. Calculations show that the proper dip to be 13.2456° (truncated to 13.24° that provides about 1.5 second earlier ( lechumra ) time) below the horizon at that time. This makes a difference of 1 minute and 10 seconds in Jerusalem during the Equinox, and 1 minute 29 seconds during the solstice as compared to the proper 13.24° versus 13°. For NY during the solstice, the difference is 1 minute 56 seconds. @todo recalculate the above based on equilux/equinox calculations.") { c -> c.getBainHashmashosRT13Point24Degrees() },
        ZmanMethod("bain-hashmashos-rt58-point5-minutes", "twilight", "Twilight Rabbeinu Tam 58.5 minutes", false, false, false, true, false, explicitElevation = false, sourceMethod = "getBainHashmashosRT58Point5Minutes", hebrewLabel = "בין השמשות רבנו תם 58.5 minutes", definition = "58.5 fixed clock minutes after sunset. Sunrise/sunset follow the profile elevation policy.", sourceDefinition = "This method returns the beginning of Bain hashmashos of Rabbeinu Tam calculated as a 58.5-minute offset after sunset. bain hashmashos is 3/4 of a mil before tzais or 3 1/4 mil after sunset. With a mil calculated as 18 minutes, 3.25 18 = 58.5 minutes.") { c -> c.getBainHashmashosRT58Point5Minutes() },
        ZmanMethod("bain-hashmashos-rt13-point5-minutes-before7-point083-degrees", "twilight", "Twilight Rabbeinu Tam 13.5 minutes Before 7.083\u00b0 below horizon", false, false, false, false, false, explicitElevation = false, sourceMethod = "getBainHashmashosRT13Point5MinutesBefore7Point083Degrees", hebrewLabel = "בין השמשות רבנו תם 13.5 minutes Before 7.083° below the horizon", definition = "Thirteen and a half fixed clock minutes before evening solar depression of 7.083°.", sourceDefinition = "This method returns the beginning of bain hashmashos based on the calculation of 13.5 minutes (3/4 of an 18-minute mil ) before shkiah calculated as getTzaisGeonim7Point083Degrees().") { c -> c.getBainHashmashosRT13Point5MinutesBefore7Point083Degrees() },
        ZmanMethod("bain-hashmashos-rt2-stars", "twilight", "Twilight Rabbeinu Tam 2Stars", false, false, false, true, false, explicitElevation = false, sourceMethod = "getBainHashmashosRT2Stars", hebrewLabel = "בין השמשות רבנו תם 2Stars", definition = "Adds five eighteenths of the interval from dawn at 19.8° below the horizon to sunrise to the evening sunset. Sunrise and sunset follow the profile elevation policy.", sourceDefinition = "This method returns the beginning of bain hashmashos of Rabbeinu Tam calculated according to the opinion of the Divrei Yosef (see Yisrael Vehazmanim) calculated 5/18th (27.77%) of the time between alos (calculated as 19.8° before sunrise) and sunrise. This is added to sunset to arrive at the time for bain hashmashos of Rabbeinu Tam.") { c -> c.getBainHashmashosRT2Stars() },
        ZmanMethod("bain-hashmashos-yereim18-minutes", "twilight", "Twilight Yereim 18 minutes", false, false, false, true, false, explicitElevation = false, sourceMethod = "getBainHashmashosYereim18Minutes", hebrewLabel = "בין השמשות יראים 18 minutes", definition = "18 fixed clock minutes before sunset under the profile elevation policy.", sourceDefinition = "This method returns the beginning of bain hashmashos (twilight) according to the Yereim (Rabbi Eliezer of Metz) calculated as 18 minutes or 3/4 of a 24-minute mil before sunset. According to the Yereim, bain hashmashos starts 3/4 of a mil before sunset and tzais or nightfall starts at sunset.") { c -> c.getBainHashmashosYereim18Minutes() },
        ZmanMethod("bain-hashmashos-yereim3-point05-degrees", "twilight", "Twilight Yereim 3.05\u00b0 above horizon", false, false, false, false, false, explicitElevation = false, sourceMethod = "getBainHashmashosYereim3Point05Degrees", hebrewLabel = "בין השמשות יראים 3.05° above horizon", definition = "Evening sun 3.05° above the geometric horizon, before sunset. This Yereim angle is above, not below, the horizon.", sourceDefinition = "This method returns the beginning of bain hashmashos (twilight) according to the Yereim (Rabbi Eliezer of Metz) calculated as the sun's position 3.05° above the horizon around the equinox / equilux , its position 18 minutes or 3/4 of an 24-minute mil before sunset. According to the Yereim, bain hashmashos starts 3/4 of a mil before sunset and tzais or nightfall starts at sunset. Note that lechumra (of about 14 seconds) a refraction value of 0.5166° as opposed to the traditional 0.566° is used. This is more inline with the actual refraction in Eretz Yisrael and is brought down by Rabbi Yedidya Manet in his Zmanei HaHalacha Lema'aseh (p. 11). That is the first source that I am aware of that calculates degree-based Yereim zmanim . The 0.5166° refraction is also used by the Luach Itim Lebinah . Calculating the Yereim's bain hashmashos using 18-minute based degrees is also suggested in the upcoming 8th edition of the zmanim Kehilchasam. For more details, see the article The Yereim's Bain Hashmashos . @todo recalculate based on equinox/equilux") { c -> c.getBainHashmashosYereim3Point05Degrees() },
        ZmanMethod("bain-hashmashos-yereim16-point875-minutes", "twilight", "Twilight Yereim 16.875 minutes", false, false, false, true, false, explicitElevation = false, sourceMethod = "getBainHashmashosYereim16Point875Minutes", hebrewLabel = "בין השמשות יראים 16.875 minutes", definition = "16.875 fixed clock minutes before sunset under the profile elevation policy.", sourceDefinition = "This method returns the beginning of bain hashmashos (twilight) according to the Yereim (Rabbi Eliezer of Metz) calculated as 16.875 minutes or 3/4 of a 22.5-minute mil before sunset. According to the Yereim, bain hashmashos starts 3/4 of a mil before sunset and tzais or nightfall starts at sunset.") { c -> c.getBainHashmashosYereim16Point875Minutes() },
        ZmanMethod("bain-hashmashos-yereim2-point8-degrees", "twilight", "Twilight Yereim 2.8\u00b0 above horizon", false, false, false, false, false, explicitElevation = false, sourceMethod = "getBainHashmashosYereim2Point8Degrees", hebrewLabel = "בין השמשות יראים 2.8° above horizon", definition = "Evening sun 2.8° above the geometric horizon, before sunset. This Yereim angle is above, not below, the horizon.", sourceDefinition = "This method returns the beginning of bain hashmashos (twilight) according to the Yereim (Rabbi Eliezer of Metz) calculated as the sun's position 2.8° above the horizon around the equinox / equilux , its position 16.875 minutes or 3/4 of an 22.5-minute mil before sunset. According to the Yereim, bain hashmashos starts 3/4 of a mil before sunset and tzais or nightfall starts at sunset. Details, including how the degrees were calculated can be seen in the documentation of getBainHashmashosYereim3Point05Degrees().") { c -> c.getBainHashmashosYereim2Point8Degrees() },
        ZmanMethod("bain-hashmashos-yereim13-point5-minutes", "twilight", "Twilight Yereim 13.5 minutes", false, false, false, true, false, explicitElevation = false, sourceMethod = "getBainHashmashosYereim13Point5Minutes", hebrewLabel = "בין השמשות יראים 13.5 minutes", definition = "13.5 fixed clock minutes before sunset under the profile elevation policy.", sourceDefinition = "This method returns the beginning of bain hashmashos (twilight) according to the Yereim (Rabbi Eliezer of Metz) calculated as 13.5 minutes or 3/4 of an 18-minute mil before sunset. According to the Yereim, bain hashmashos starts 3/4 of a mil before sunset and tzais or nightfall starts at sunset.") { c -> c.getBainHashmashosYereim13Point5Minutes() },
        ZmanMethod("bain-hashmashos-yereim2-point1-degrees", "twilight", "Twilight Yereim 2.1\u00b0 above horizon", false, false, false, false, false, explicitElevation = false, sourceMethod = "getBainHashmashosYereim2Point1Degrees", hebrewLabel = "בין השמשות יראים 2.1° above horizon", definition = "Evening sun 2.1° above the geometric horizon, before sunset. This Yereim angle is above, not below, the horizon.", sourceDefinition = "This method returns the beginning of bain hashmashos according to the Yereim (Rabbi Eliezer of Metz) calculated as the sun's position 2.1° above the horizon around the equinox / equilux in Yerushalayim, its position 13.5 minutes or 3/4 of an 18-minute mil before sunset. According to the Yereim, bain hashmashos starts 3/4 of a mil before sunset and tzais or nightfall starts at sunset. Details, including how the degrees were calculated can be seen in the documentation of getBainHashmashosYereim3Point05Degrees().") { c -> c.getBainHashmashosYereim2Point1Degrees() },
        ZmanMethod("tzais-geonim3-point7-degrees", "nightfall", "Nightfall Geonim 3.7\u00b0 below horizon", false, false, false, false, false, explicitElevation = false, sourceMethod = "getTzaisGeonim3Point7Degrees", hebrewLabel = "צאת הכוכבים גאונים 3.7° below the horizon", definition = "Evening sun 3.7° below the geometric horizon. A solar angle, not a fixed-minute interval; the time may be unavailable at high latitudes.", sourceDefinition = "This method returns the tzais (nightfall) based on the opinion of the Geonim calculated at the sun's position at 3.7° below GEOMETRIC_ZENITH (90°), calculated as the position of the sun 13.5 minutes after sunset, the time it takes to walk 3/4 of a mil at 18 minutes a mil, or 13.5 minutes after sunset. The sun is 3.7° below GEOMETRIC_ZENITH at this time in Jerusalem around the equinox / equilux . This does not cover the 26.46 it takes to walk 49 amos (the heref ayin of bain hashmashos of Rav Yosi) at the pace of an 18-minute mil. Rabbi Yedidya Manet in his Zmanei HaHalacha Lema'aseh (5th edition, vol. I page 36, no. 22) lists 3.65° as the value for this tzais , however it is based on sunset calculated using a refreaction value of 31′ (arcminutes) or 0.516° (page 16) based on his calculations of the refraction value in Israel at the autumn equinox (something he himself questions in vol II, page 36). Even for Israel, most consider that refraction value too low. Regardless, the dip for tzais must be based on sunset using a specific refraction model (and solar radius), and this library currently uses a global average refraction value of 34′ (arcminutes) or 0.566°. Based on the global average refraction for sunset, this tzais calculates as 3.7°.") { c -> c.getTzaisGeonim3Point7Degrees() },
        ZmanMethod("tzais-geonim3-point8-degrees", "nightfall", "Nightfall Geonim 3.8\u00b0 below horizon", false, false, false, false, false, explicitElevation = false, sourceMethod = "getTzaisGeonim3Point8Degrees", hebrewLabel = "צאת הכוכבים גאונים 3.8° below the horizon", definition = "Evening sun 3.8° below the geometric horizon. A solar angle, not a fixed-minute interval; the time may be unavailable at high latitudes.", sourceDefinition = "This method returns the tzais (nightfall) based on the opinion of the Geonim calculated at the sun's position at 3.8° below GEOMETRIC_ZENITH (90°), calculated as the position of the sun 13.5 minutes after sunset, the time it takes to walk 3/4 of a mil at 18 minutes a mil, plus 30 seconds for the time it takes to walk 49 amos (the heref ayin of bain hashmashos of Rav Yosi). With this being an 18-minutes mil, 49 amos would take 26.46, rounded to 30 seconds), for a total of 14 minutes after sunset. The sun is 3.8° below GEOMETRIC_ZENITH at this time in Jerusalem around the equinox / equilux .") { c -> c.getTzaisGeonim3Point8Degrees() },
        ZmanMethod("tzais-geonim5-point95-degrees", "nightfall", "Nightfall Geonim 5.95\u00b0 below horizon", false, false, false, false, false, explicitElevation = false, sourceMethod = "getTzaisGeonim5Point95Degrees", hebrewLabel = "צאת הכוכבים גאונים 5.95° below the horizon", definition = "Evening sun 5.95° below the geometric horizon. A solar angle, not a fixed-minute interval; the time may be unavailable at high latitudes.", sourceDefinition = "This method returns the tzais (nightfall) based on the opinion of the Geonim calculated at the sun's position at 5.95° below GEOMETRIC_ZENITH (90°), calculated as the position of the sun 24 minutes after sunset in Jerusalem around the equinox / equilux . The 24 minutes is based on the Baal Hatanya's calculation of 18 minutes (3/4 of a 24 minute mil) + 4 minutes for shkiah amitis + 2 minutes for bain hashmashos of Rav Yosi. See Hazmanim Bahalacha vol II, ch. 50, no. 5, p. 512-513, ch. 47, and Yisrael Vehazmanim Vol III, ch. 13, no. 53, p. 1026 . Among sources he mentions for this zman is Rabbi Yehuda (Leo) Levi's calculations in Jewish Chrononomy and other sources. Calculations show that the time is closer to 5.93° and was seemingly rounded to 5.95°. Chabad calendars usually use the 6°-based getTzaisBaalHatanya() that is built on this same calculation. Rabbi Yedidya Manet in his Zmanei HaHalacha Lema'aseh (5th edition, vol. I page 36, no. 24) lists 5.88° as the value for this tzais , however it is based on sunset calculated using a refreaction value of 31′ (arcminutes) or 0.516° (page 16) based on his calculations of the refraction value in Israel at the autumn equinox (something he himself questions in vol II, page 36). Even for Israel, most consider that refraction value too low. Regardless, the dip for tzais must be based on sunset using a specific refraction model (and solar radius), and this library currently uses a global average refraction value of 34′ (arcminutes) or 0.566°. Based on the global average refraction for sunset, this tzais calculates as 5.93° (rounded by most calendars to 5.95°).") { c -> c.getTzaisGeonim5Point95Degrees() },
        ZmanMethod("tzais-geonim4-point66-degrees", "nightfall", "Nightfall Geonim 4.66\u00b0 below horizon", false, false, false, false, false, explicitElevation = false, sourceMethod = "getTzaisGeonim4Point66Degrees", hebrewLabel = "צאת הכוכבים גאונים 4.66° below the horizon", definition = "Evening sun 4.66° below the geometric horizon. A solar angle, not a fixed-minute interval; the time may be unavailable at high latitudes.", sourceDefinition = "This method returns the tzais (nightfall) based on the opinion of the Geonim calculated as 3/4 of a mil based on a 24-minute mil, or 18 minutes. It is the sun's position at 4.66° below the western horizon. This is a very early zman and should not be relied on without Rabbinical guidance. This does not cover the 35.28 seconds it takes to walk 49 amos (the heref ayin of bain hashmashos of Rav Yosi) at the pace of a 24-minute mil. See getTzaisGeonim4Point8Degrees() for a time that covers the heref ayin . Rabbi Yedidya Manet in his Zmanei HaHalacha Lema'aseh (5th edition, vol. I page 36, no. 24) lists 4.61° as the value for this tzais , however it is based on sunset calculated using a refreaction value of 31′ (arcminutes) or 0.516° (page 16) based on his calculations of the refraction value in Israel at the autumn equinox (something he himself questions in vol II, page 36). Even for Israel, most consider that refraction value too low. Regardless, the dip for tzais must be based on sunset using a specific refraction model (and solar radius), and this library currently uses a global average refraction value of 34′ (arcminutes) or 0.566°. Based on the global average refraction for sunset, this tzais calculates as 4.66°.") { c -> c.getTzaisGeonim4Point66Degrees() },
        ZmanMethod("tzais-geonim4-point42-degrees", "nightfall", "Nightfall Geonim 4.42\u00b0 below horizon", false, false, false, false, false, explicitElevation = false, sourceMethod = "getTzaisGeonim4Point42Degrees", hebrewLabel = "צאת הכוכבים גאונים 4.42° below the horizon", definition = "Evening sun 4.42° below the geometric horizon. A solar angle, not a fixed-minute interval; the time may be unavailable at high latitudes.", sourceDefinition = "This method returns the tzais (nightfall) based on the opinion of the Geonim calculated as 3/4 of a mil , based on a 22.5-minute mil, or 16.875 minutes. It is the sun's position at 4.42° below the western horizon. This is a very early zman and should not be relied on without Rabbinical guidance. This does not cover the 33.07 seconds it takes to walk 49 amos (the heref ayin of bain hashmashos of Rav Yosi) at the pace of a 22.5 minute-mil. Rabbi Yedidya Manet in his Zmanei HaHalacha Lema'aseh (5th edition, vol. I page 36, no. 23) lists 4.37° as the value for this tzais , however it is based on sunset calculated using a refreaction value of 31′ (arcminutes) or 0.516° (page 16) based on his calculations of the refraction value in Israel at the autumn equinox (something he himself questions in vol II, page 36). Even for Israel, most consider that refraction value too low. Regardless, the dip for tzais must be based on sunset using a specific refraction model (and solar radius), and this library currently uses a global average refraction value of 34′ (arcminutes) or 0.566°. Based on the global average refraction for sunset, this tzais calculates as 4.42°.") { c -> c.getTzaisGeonim4Point42Degrees() },
        ZmanMethod("tzais-geonim4-point8-degrees", "nightfall", "Nightfall Geonim 4.8\u00b0 below horizon", false, false, false, false, false, explicitElevation = false, sourceMethod = "getTzaisGeonim4Point8Degrees", hebrewLabel = "צאת הכוכבים גאונים 4.8° below the horizon", definition = "Evening sun 4.8° below the geometric horizon. A solar angle, not a fixed-minute interval; the time may be unavailable at high latitudes.", sourceDefinition = "This method returns the tzais (nightfall) based on the opinion of the Geonim calculated as the sun's position below the horizon at a time of 18.6 minutes after sunset. This is calculated as 3/4 of a 24-minute mil , plus 0.6 minutes for the time to walk 49 amos for bain hashmashos of Rav Yosi (with this zman based on a 24-minute mil, 49 amos would take 35.28 seconds to walk), for a total of 18.6 minutes after sunset. This calculates to the sun's position at 4.8° below the western horizon. This is based on Rav Yechiel Michel Shlezinger's sefer Aizehu Bain Hashmashos , Rabbi Yehuda (Leo) Levi's calculations in Zmanei Hayom BaHalacha p. 37. At this point, 3 medium sized stars are visible to a non-expert with good vision with effort. An expert knowing where to look can see the 3 medium stars as early as 15 minutes after sunset. This is explained in detail in Hazmanim Bahalacha vol II, ch. 41, no. 6 (p. 372-373, ch. 47, no. 11-12 (p. 491-493) where it is clear that medium sized stars would be visible as early as 14 minutes after sunset (13.5 minutes for 3/4 of an 18 minute Mil, plus 0.5 minutes for bain Hashmashos of Rav Yosi) to an expert. See more details on this earlier zman at getTzaisGeonim3Point8Degrees(). This is an early zman for tzais and should not be relied on without Rabbinical guidance.") { c -> c.getTzaisGeonim4Point8Degrees() },
        ZmanMethod("tzais-geonim6-point45-degrees", "nightfall", "Nightfall Geonim 6.45\u00b0 below horizon", false, false, false, false, false, explicitElevation = false, sourceMethod = "getTzaisGeonim6Point45Degrees", hebrewLabel = "צאת הכוכבים גאונים 6.45° below the horizon", definition = "Evening sun 6.45° below the geometric horizon. A solar angle, not a fixed-minute interval; the time may be unavailable at high latitudes.", sourceDefinition = "This method returns the tzais (nightfall) based on the opinion of the Geonim as calculated by Rabbi Yechiel Michel Tucazinsky as the position of the sun no later than 31 minutes after sea-level sunset in Jerusalem (the Birur halacha shows that Rav Tucazinsky's calculations for sunset, listed as 28 minutes in this case, were about 3 minutes later than reality), and at the height of the summer solstice, this zman , calculations show that 30.75 minutes after shkiah computes to 6.45° below GEOMETRIC_ZENITH. This calculation is found in the Birur Halacha Yoreh Deah 262 and it is the commonly used zman in Israel. It is also used in the Luach Itim Lebinah . it should be noted that this differs from the 6.1° / 6.2° calculation for Rabbi Tucazinsky's time as calculated by the Hazmanim Bahalacha Vol II chapter 50:7 (page 515). Calculations show that 6.45° at the equinox is 26.5 minutes after shkiah around the equinox / equilux .") { c -> c.getTzaisGeonim6Point45Degrees() },
        ZmanMethod("tzais-geonim7-point083-degrees", "nightfall", "Nightfall Geonim 7.083\u00b0 below horizon", false, false, false, false, false, explicitElevation = false, sourceMethod = "getTzaisGeonim7Point083Degrees", hebrewLabel = "צאת הכוכבים גאונים 7.083° below the horizon", definition = "Evening sun 7.083° below the geometric horizon. A solar angle, not a fixed-minute interval; the time may be unavailable at high latitudes.", sourceDefinition = "This method returns the tzais (nightfall) based on the opinion of the Geonim calculated when the sun's position 7.083° (or 7° 5′) below the western horizon. This is often referred to as 7° 5′ or 7° and 5′ minutes. This calculation is based on the observation of 3 medium-sized stars by Dr. Baruch (Berthold) Cohn in his luach Tabellen enthaltend die Zeitangaben für den Beginn der Nacht und des Tages für die Breitengrade + 66 bis -38 published in Strasbourg, France in 1899. This calendar was very popular in Europe, and many other calendars based their tzais time on it. Rav Dovid Tzvi Hoffman in his שו״ת מלמד להועיל in an exchange of letters with Baruch Cohn in Orach Chaim 30 agreed to this zman (page 36), as did the שו״ת בני ציון and the תנובת שדה . It is very close to the time of the מקור חסד of the Sefer chasidim. It is close to the position of the sun 30 minutes after sunset in Jerusalem around the equinox / equilux , but not Exactly. The actual position of the sun 30 minutes after sunset in Jerusalem at the equilux is 7.205° and 7.199° at the equinox. See Hazmanim Bahalacha vol 2, pages 520-521 for more details.") { c -> c.getTzaisGeonim7Point083Degrees() },
        ZmanMethod("tzais-geonim7-point67-degrees", "nightfall", "Nightfall Geonim 7.67\u00b0 below horizon", false, false, false, false, false, explicitElevation = false, sourceMethod = "getTzaisGeonim7Point67Degrees", hebrewLabel = "צאת הכוכבים גאונים 7.67° below the horizon", definition = "Evening sun 7.67° below the geometric horizon. A solar angle, not a fixed-minute interval; the time may be unavailable at high latitudes.", sourceDefinition = "This method returns tzais (nightfall) based on the opinion of the Geonim calculated as 45 minutes after sunset during the summer solstice in New York, when the neshef (twilight) is the longest. The sun's position at this time computes to 7.67° below the western horizon. See Igros Moshe Even Haezer 4, Ch. 4 (regarding tzais for krias Shema ). It is also mentioned in Rabbi Heber's Shaarei Zmanim on in chapter 10 (page 87) and chapter 12 (page 108) . Also see the time of 45 minutes in Rabbi Simcha Bunim Cohen's The radiance of Shabbos as the earliest zman for New York. This zman is also listed in the Divrei Shalom Vol. III, chapter 75 , and Bais Av\"i Vol. III, chapter 117 . This zman is also listed in the Divrei Shalom etc. chapter 177. Since this zman depends on the level of light, Rabbi Yaakov Shakow presented this degree-based calculation to Rabbi Rabbi Shmuel Kamenetsky who agreed to it. @todo add hyperlinks to source of Divrei Shalom once it is located.") { c -> c.getTzaisGeonim7Point67Degrees() },
        ZmanMethod("tzais-geonim9-point3-degrees", "nightfall", "Nightfall Geonim 9.3\u00b0 below horizon", false, false, false, false, false, explicitElevation = false, sourceMethod = "getTzaisGeonim9Point3Degrees", hebrewLabel = "צאת הכוכבים גאונים 9.3° below the horizon", definition = "Evening sun 9.3° below the geometric horizon. A solar angle, not a fixed-minute interval; the time may be unavailable at high latitudes.", sourceDefinition = "This method returns the tzais (nightfall) based on the calculations used in the Luach Itim Lebinah as the stringent time for tzais . It is calculated as the sun's position at 9.3° below the western horizon.") { c -> c.getTzaisGeonim9Point3Degrees() },
        ZmanMethod("tzais-geonim9-point75-degrees", "nightfall", "Nightfall Geonim 9.75\u00b0 below horizon", false, false, false, false, false, explicitElevation = false, sourceMethod = "getTzaisGeonim9Point75Degrees", hebrewLabel = "צאת הכוכבים גאונים 9.75° below the horizon", definition = "Evening sun 9.75° below the geometric horizon. A solar angle, not a fixed-minute interval; the time may be unavailable at high latitudes.", sourceDefinition = "This method returns the tzais (nightfall) based on the opinion of the Geonim calculated as 60 minutes after sunset around the equinox / equilux , the day that a solar hour is 60 minutes in New York. The sun's position at this time computes to 9.75° below the western horizon. This is the opinion of Rabbi Eliyahu Henkin . This also follows the opinion of Rabbi Shmuel Kamenetsky . Rabbi Yaakov Shakow presented these degree-based times to Rabbi Shmuel Kamenetsky who agreed to them. @todo recalculate based on equinox / equilux.") { c -> c.getTzaisGeonim9Point75Degrees() },
        ZmanMethod("tzais60-minutes", "nightfall", "Nightfall 60 minutes", false, false, false, true, false, explicitElevation = false, sourceMethod = "getTzais60Minutes", hebrewLabel = "צאת הכוכבים 60 minutes", definition = "60 fixed clock minutes after sunset. Sunrise/sunset follow the profile elevation policy.", sourceDefinition = "This method returns the tzais (nightfall) based on the opinion of the Chavas Yair and Divrei Malkiel that the time to walk the distance of a mil is 15 minutes, for a total of 60 minutes for 4 mil after getSunsetBasedOnElevationSetting()(depends on the isUseElevation() setting). See detailed documentation explaining the 60 minute concept at getAlos60Minutes().") { c -> c.getTzais60Minutes() },
        ZmanMethod("tzais-ateret-torah", "nightfall", "Nightfall Ateret Torah", false, true, false, true, false, explicitElevation = false, sourceMethod = "getTzaisAteretTorah", hebrewLabel = "צאת הכוכבים עטרת תורה", definition = "Adds the explicitly configured Ateret Torah fixed-minute offset to sunset under the profile elevation policy. The offset also defines the end boundary of the Ateret Torah temporal-day family.", sourceDefinition = "This method returns tzais usually calculated as 40 minutes (configurable to any offset via setAteretTorahSunsetOffset(double)) after sunset. Please note that Chacham Yosef Harari-Raful of Yeshivat Ateret Torah who uses this time, does so only for calculating various other zmanei hayom such as Sof Zman Krias Shema and Plag Hamincha . His calendars do not publish a zman for Tzais . It should also be noted that Chacham Harari-Raful provided a 25 minute zman for Israel. This API uses 40 minutes year round in any place on the globe by default. This offset can be changed by calling setAteretTorahSunsetOffset(double).") { c -> c.getTzaisAteretTorah() },
        ZmanMethod("sof-zman-shma-ateret-torah", "shema", "Latest Shema Ateret Torah \u00b7 Day: Dawn 72 temporal minutes \u2192 Nightfall Ateret Torah", false, true, false, true, false, explicitElevation = false, sourceMethod = "getSofZmanShmaAteretTorah", hebrewLabel = "סוף זמן קריאת שמע עטרת תורה", definition = "3 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. Day: Dawn 72 temporal minutes → Nightfall Ateret Torah", sourceDefinition = "This method returns the latest zman krias shema (time to recite Shema in the morning) based on the calculation of Chacham Yosef Harari-Raful of Yeshivat Ateret Torah, that the day starts 1/10th of the day before sunrise and is usually calculated as ending 40 minutes after sunset (configurable to any offset via setAteretTorahSunsetOffset(double)). Shaos zmaniyos are calculated based on this day and added to alos to reach this time. This time is 3 shaos zmaniyos (temporal hours) after alos 72 zmaniyos . Note: Based on this calculation chatzos will not be at midday.") { c -> c.getSofZmanShmaAteretTorah() },
        ZmanMethod("sof-zman-tfila-ateret-torah", "prayer", "Latest teffilah Ateret Torah \u00b7 Day: Dawn 72 temporal minutes \u2192 Nightfall Ateret Torah", false, true, false, true, false, explicitElevation = false, sourceMethod = "getSofZmanTfilaAteretTorah", hebrewLabel = "סוף זמן תפילה עטרת תורה", definition = "4 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. Day: Dawn 72 temporal minutes → Nightfall Ateret Torah", sourceDefinition = "This method returns the latest zman tfila (time to recite the morning prayers) based on the calculation of Chacham Yosef Harari-Raful of Yeshivat Ateret Torah, that the day starts 1/10th of the day before sunrise and is usually calculated as ending 40 minutes after sunset (configurable to any offset via setAteretTorahSunsetOffset(double)). shaos zmaniyos are calculated based on this day and added to getAlos72Zmanis() to reach this time. This time is 4 getShaahZmanisAteretTorah() after getAlos72Zmanis(). Note: Based on this calculation chatzos will not be at midday. Sources for an asymmetrical day-based calculation can be seen in the documentation of getSofZmanShmaAlos16Point1DegreesToTzaisGeonim7Point083Degrees.") { c -> c.getSofZmanTfilaAteretTorah() },
        ZmanMethod("mincha-gedola-ateret-torah", "mincha-gedolah", "Earliest Mincha Ateret Torah \u00b7 Day: Dawn 72 temporal minutes \u2192 Nightfall Ateret Torah", false, true, false, true, false, explicitElevation = false, sourceMethod = "getMinchaGedolaAteretTorah", hebrewLabel = "מנחה גדולה עטרת תורה", definition = "6.5 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. Day: Dawn 72 temporal minutes → Nightfall Ateret Torah", sourceDefinition = "This method returns the time of mincha gedola based on the calculation of Chacham Yosef Harari-Raful of Yeshivat Ateret Torah, that the day starts 1/10th of the day before sunrise and is usually calculated as ending 40 minutes after sunset (configurable to any offset via setAteretTorahSunsetOffset(double)). This is the preferred earliest time to pray mincha according to the opinion of the Rambam and others. For more information on this see the documentation on mincha gedola . This is calculated as 6.5 solar hours after alos . The calculation used is 6.5 getShaahZmanisAteretTorah() after alos .") { c -> c.getMinchaGedolaAteretTorah() },
        ZmanMethod("mincha-ketana-ateret-torah", "mincha-ketanah", "Mincha ketanah Ateret Torah \u00b7 Day: Dawn 72 temporal minutes \u2192 Nightfall Ateret Torah", false, true, false, true, false, explicitElevation = false, sourceMethod = "getMinchaKetanaAteretTorah", hebrewLabel = "מנחה קטנה עטרת תורה", definition = "9.5 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. Day: Dawn 72 temporal minutes → Nightfall Ateret Torah", sourceDefinition = "This method returns the time of mincha ketana based on the calculation of Chacham Yosef Harari-Raful of Yeshivat Ateret Torah, that the day starts 1/10th of the day before sunrise and is usually calculated as ending 40 minutes after sunset (configurable to any offset via setAteretTorahSunsetOffset(double)). This is the preferred earliest time to pray mincha according to the opinion of the Rambam and others. For more information on this see the documentation on mincha gedola . This is calculated as 9.5 solar hours after alos . The calculation used is 9.5 getShaahZmanisAteretTorah() after alos .") { c -> c.getMinchaKetanaAteretTorah() },
        ZmanMethod("plag-hamincha-ateret-torah", "plag", "Plag Ateret Torah \u00b7 Day: Dawn 72 temporal minutes \u2192 Nightfall Ateret Torah", false, true, false, true, false, explicitElevation = false, sourceMethod = "getPlagHaminchaAteretTorah", hebrewLabel = "פלג המנחה עטרת תורה", definition = "10.75 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. Day: Dawn 72 temporal minutes → Nightfall Ateret Torah", sourceDefinition = "This method returns the time of plag hamincha based on the calculation of Chacham Yosef Harari-Raful of Yeshivat Ateret Torah, that the day starts 1/10th of the day before sunrise and is usually calculated as ending 40 minutes after sunset (configurable to any offset via setAteretTorahSunsetOffset(double)). shaos zmaniyos are calculated based on this day and added to alos to reach this time. This time is 10.75 shaos zmaniyos (temporal hours) after dawn.") { c -> c.getPlagHaminchaAteretTorah() },
        ZmanMethod("tzais72-zmanis", "nightfall", "Nightfall 72 temporal minutes", false, false, false, true, false, explicitElevation = false, sourceMethod = "getTzais72Zmanis", hebrewLabel = "צאת הכוכבים 72 temporal minutes", definition = "72 temporal minutes (one sixtieth of the sunrise-to-sunset temporal hour) after sunset. Sunrise/sunset follow the profile elevation policy.", sourceDefinition = "Method to return tzais (dusk) calculated as 72 minutes zmaniyos, or 1/10th of the day after getSeaLevelSunset() sea level sunset. This is the way that the Minchas Cohen in Ma'amar 2:4 calculates Rebbeinu Tam's time of tzais . It should be noted that this calculation results in the shortest time from sunset to tzais being during the winter solstice, the longest at the summer solstice and 72 clock minutes at the equinox. This does not match reality, since there is no direct relationship between the length of the day and twilight. The shortest twilight is during the equinox, the longest is during the summer solstice, and in the winter with the shortest daylight, the twilight period is longer than during the equinoxes.") { c -> c.getTzais72Zmanis() },
        ZmanMethod("tzais90-zmanis", "nightfall", "Nightfall 90 temporal minutes", false, false, false, true, false, explicitElevation = false, sourceMethod = "getTzais90Zmanis", hebrewLabel = "צאת הכוכבים 90 temporal minutes", definition = "90 temporal minutes (one sixtieth of the sunrise-to-sunset temporal hour) after sunset. Sunrise/sunset follow the profile elevation policy.", sourceDefinition = "Method to return tzais (dusk) calculated using 90 minutes zmaniyos or 1/8th of the day after getSeaLevelSunset() sea level sunset. This time is known in Yiddish as the achtel (an eighth) zman used in various kehilos .") { c -> c.getTzais90Zmanis() },
        ZmanMethod("tzais96-zmanis", "nightfall", "Nightfall 96 temporal minutes", false, false, false, true, false, explicitElevation = false, sourceMethod = "getTzais96Zmanis", hebrewLabel = "צאת הכוכבים 96 temporal minutes", definition = "96 temporal minutes (one sixtieth of the sunrise-to-sunset temporal hour) after sunset. Sunrise/sunset follow the profile elevation policy.", sourceDefinition = "Method to return tzais (dusk) calculated using 96 minutes zmaniyos or 1/7.5 of the day after sea level sunset.") { c -> c.getTzais96Zmanis() },
        ZmanMethod("tzais90-minutes", "nightfall", "Nightfall 90 minutes", false, false, false, true, false, explicitElevation = false, sourceMethod = "getTzais90Minutes", hebrewLabel = "צאת הכוכבים 90 minutes", definition = "90 fixed clock minutes after sunset. Sunrise/sunset follow the profile elevation policy.", sourceDefinition = "Method to return tzais (dusk) calculated as 90 minutes after getSunsetBasedOnElevationSetting (depends on the isUseElevation() setting). This method returns tzais (nightfall) based on the opinion of the Magen Avraham that the time to walk the distance of a mil according to the Rambam 's opinion is 18 minutes, for a total of 90 minutes based on the opinion of Ula who calculated tzais as 5 mil after elevation adjusted shkiah (sunset). A similar calculation getTzais19Point8Degrees() uses solar position calculations based on this time.") { c -> c.getTzais90Minutes() },
        ZmanMethod("tzais120-minutes", "nightfall", "Nightfall 120 minutes", false, false, false, true, false, explicitElevation = false, sourceMethod = "getTzais120Minutes", hebrewLabel = "צאת הכוכבים 120 minutes", definition = "120 fixed clock minutes after sunset. Sunrise/sunset follow the profile elevation policy.", sourceDefinition = "This method should be used lechumra only and returns tzais (nightfall) based on the calculations of Rav Chaim Naeh that the time to walk the distance of a mil according to the Rambam 's opinion is 2/5 of an hour (24 minutes) for a total of 120 minutes based on the opinion of Ula who calculated tzais as 5 mil after getSunsetBasedOnElevationSetting() (depends on the isUseElevation() setting). A similar calculation getTzais26Degrees() uses degree-based calculations based on this 120 minute calculation Since the zman is extremely late and at a point that is long past the 18° point where the darkest point is reached, it should only be used lechumra , such as delaying the start of nighttime mitzvos .") { c -> c.getTzais120Minutes() },
        ZmanMethod("tzais120-zmanis", "nightfall", "Nightfall 120 temporal minutes", false, false, false, true, false, explicitElevation = false, sourceMethod = "getTzais120Zmanis", hebrewLabel = "צאת הכוכבים 120 temporal minutes", definition = "120 temporal minutes (one sixtieth of the sunrise-to-sunset temporal hour) after sunset. Sunrise/sunset follow the profile elevation policy.", sourceDefinition = "This method should be used lechumra only and returns tzais (dusk) calculated using 120 minutes zmaniyos after sea level sunset. Since the zman is extremely late and at a time when the sun is well below the 18° point (scientifically the darkest point) in most places on the globe, it should only be used lechumra , such as delaying the start of nighttime mitzvos .") { c -> c.getTzais120Zmanis() },
        ZmanMethod("tzais16-point1-degrees", "nightfall", "Nightfall 16.1\u00b0 below horizon", false, false, false, false, false, explicitElevation = false, sourceMethod = "getTzais16Point1Degrees", hebrewLabel = "צאת הכוכבים 16.1° below the horizon", definition = "Evening sun 16.1° below the geometric horizon. A solar angle, not a fixed-minute interval; the time may be unavailable at high latitudes.", sourceDefinition = "This calculates the time of tzais at the point when the sun is 16.1° below the horizon. This is the sun's dip below the horizon 72 minutes after sunset according Rabbeinu Tam's calculation of tzais around the equinox / equilux in Jerusalem. The question of equinox VS equilux is complex, with Rabbi Meir Posen in the Ohr Meir of the opinion that the equilux should be used. See Yisrael Vehazmanim vol I, 34:1:4. Rabbi Yedidya Manet in his Zmanei HaHalacha Lema'aseh (4th edition part 2, pages and 22 and 24) and Rabbi Yonah Mertzbuch (in a letter published by Rabbi Manet) are of the opinion that the astronomical equinox should be used. The difference adds up to about 9 seconds, too trivial to make much of a difference. For information on how this is calculated see the comments on getAlos16Point1Degrees().") { c -> c.getTzais16Point1Degrees() },
        ZmanMethod("tzais26-degrees", "nightfall", "Nightfall 26\u00b0 below horizon", false, false, false, false, false, explicitElevation = false, sourceMethod = "getTzais26Degrees", hebrewLabel = "צאת הכוכבים 26° below the horizon", definition = "Evening sun 26° below the geometric horizon. A solar angle, not a fixed-minute interval; the time may be unavailable at high latitudes.", sourceDefinition = "This method should be used lechumra only and returns tzais based on when the sun is 26° below the horizon. For information on how this is calculated see the comments on getAlos26Degrees(). Since the zman is extremely late and at a point when it is long past the 18° point where the darkest point is reached, it should only be used lechumra such as delaying the start of nighttime mitzvos .") { c -> c.getTzais26Degrees() },
        ZmanMethod("tzais18-degrees", "nightfall", "Nightfall 18\u00b0 below horizon", false, false, false, false, false, explicitElevation = false, sourceMethod = "getTzais18Degrees", hebrewLabel = "צאת הכוכבים 18° below the horizon", definition = "Evening sun 18° below the geometric horizon. A solar angle, not a fixed-minute interval; the time may be unavailable at high latitudes.", sourceDefinition = "For information on how this is calculated see the comments on getAlos18Degrees()") { c -> c.getTzais18Degrees() },
        ZmanMethod("tzais19-point8-degrees", "nightfall", "Nightfall 19.8\u00b0 below horizon", false, false, false, false, false, explicitElevation = false, sourceMethod = "getTzais19Point8Degrees", hebrewLabel = "צאת הכוכבים 19.8° below the horizon", definition = "Evening sun 19.8° below the geometric horizon. A solar angle, not a fixed-minute interval; the time may be unavailable at high latitudes.", sourceDefinition = "For information on how this is calculated see the comments on getAlos19Point8Degrees().") { c -> c.getTzais19Point8Degrees() },
        ZmanMethod("tzais96-minutes", "nightfall", "Nightfall 96 minutes", false, false, false, true, false, explicitElevation = false, sourceMethod = "getTzais96Minutes", hebrewLabel = "צאת הכוכבים 96 minutes", definition = "96 fixed clock minutes after sunset. Sunrise/sunset follow the profile elevation policy.", sourceDefinition = "A method to return tzais (dusk) calculated as 96 minutes after sunset or getSeaLevelSunset() sea level sunset (depending on the isUseElevation() setting). For information on how this is calculated see the comments on getAlos96Minutes().") { c -> c.getTzais96Minutes() },
        ZmanMethod("fixed-local-chatzos-hayom", "chatzos", "Fixed local Midday", false, false, false, false, false, explicitElevation = false, sourceMethod = "getFixedLocalChatzosHayom", hebrewLabel = "Fixed local חצות היום", definition = "Local mean noon from longitude: four clock minutes per degree, expressed in the actual civil timezone including daylight saving. Does not depend on sunrise or sunset.", sourceDefinition = "A method that returns the local time for fixed chatzos . This time is noon and adjusted from standard time to account for the local latitude. The 360° of the globe divided by 24 calculates to 15° per hour with 4 minutes per degree, so at a longitude of 0 , 15, 30 etc... Chatzos is at exactly 12:00 noon. This is the time of chatzos according to the Aruch Hashulchan in Orach Chaim 233:14 and Rabbi Moshe Feinstein in Igros Moshe Orach Chaim 1:24 and 2:20 . Lakewood, N.J., with a longitude of -74.222, is 0.778 away from the closest multiple of 15 at -75°. This is multiplied by 4 to yield 3 minutes and 7 seconds for a chatzos of 11:56:53. This method is not tied to the theoretical 15° time zones, but will adjust to the actual time zone and Daylight saving time .") { c -> c.getFixedLocalChatzosHayom() },
        ZmanMethod("sof-zman-kidush-levana-between-moldos", "lunar", "Latest Kiddush Levanah Between Moldos", false, false, false, false, false, explicitElevation = false, sourceMethod = "getSofZmanKidushLevanaBetweenMoldos", hebrewLabel = "סוף זמן קידוש לבנה Between Moldos", definition = "Half a mean lunar month after the molad: 14 days, 18 hours, 22 minutes and 1⅔ seconds. Shown only on the local date of that instant.", sourceDefinition = "Returns the latest time of Kiddush Levana according to the Maharil's opinion that it is calculated as halfway between molad and molad . This adds half the 29 days, 12 hours and 793 chalakim time between molad and molad (14 days, 18 hours, 22 minutes and 666 milliseconds) to the month's molad . The sof zman Kiddush Levana will be returned even if it occurs during the day. To limit the time to between tzais and alos , see Instant).") { c -> c.getSofZmanKidushLevanaBetweenMoldos() },
        ZmanMethod("sof-zman-kidush-levana15-days", "lunar", "Latest Kiddush Levanah 15 days", false, false, false, false, false, explicitElevation = false, sourceMethod = "getSofZmanKidushLevana15Days", hebrewLabel = "סוף זמן קידוש לבנה 15 days", definition = "Fifteen elapsed 24-hour days after the molad. Shown only on the local date of that instant.", sourceDefinition = "Returns the latest time of Kiddush Levana calculated as 15 days after the molad. This is the opinion of the Shulchan Aruch (Orach Chaim 426). It should be noted that some opinions hold that the Rema who brings down the opinion of the Maharil's of calculating Instant) halfway between molad and molad is of the opinion that the Mechaber agrees to his opinion. Also see the Aruch Hashulchan. For additional details on the subject, See Rabbi Dovid Heber's very detailed write-up in Siman Daled (chapter 4) of Shaarei Zmanim . The sof zman Kiddush Levana will be returned even if it occurs during the day. To limit the time to between tzais and alos , see Instant).") { c -> c.getSofZmanKidushLevana15Days() },
        ZmanMethod("tchilas-zman-kidush-levana3-days", "lunar", "Earliest Kiddush Levanah 3 days", false, false, false, false, false, explicitElevation = false, sourceMethod = "getTchilasZmanKidushLevana3Days", hebrewLabel = "תחילת זמן קידוש לבנה 3 days", definition = "Three elapsed 24-hour days after the molad. Shown only on the local date of that instant.", sourceDefinition = "Returns the earliest time of Kiddush Levana according to Rabbeinu Yonah 's opinion that it can be said 3 days after the molad . The time will be returned even if it occurs during the day when Kiddush Levana can't be said. Use Instant) if you want to limit the time to night hours.") { c -> c.getTchilasZmanKidushLevana3Days() },
        ZmanMethod("zman-molad", "lunar", "Molad", false, false, false, false, false, explicitElevation = false, sourceMethod = "getZmanMolad", hebrewLabel = "מולד", definition = "The traditional calculated mean lunar conjunction, expressed as an exact instant in this location’s timezone, on its applicable local date.", sourceDefinition = "Returns the point in time of Molad as a Instant Object. For the traditional day of week, hour, minute and chalakim, getMoladAsInstant() and the not yet completed com.kosherjava.zmanim.hebrewcalendar.HebrewDateFormatter that will have formatting for this.") { c -> c.getZmanMolad() },
        ZmanMethod("tchilas-zman-kidush-levana7-days", "lunar", "Earliest Kiddush Levanah 7 days", false, false, false, false, false, explicitElevation = false, sourceMethod = "getTchilasZmanKidushLevana7Days", hebrewLabel = "תחילת זמן קידוש לבנה 7 days", definition = "Seven elapsed 24-hour days after the molad. Shown only on the local date of that instant.", sourceDefinition = "Returns the earliest time of Kiddush Levana according to the opinions that it should not be said until 7 days after the molad . The time will be returned even if it occurs during the day when Kiddush Levana can't be recited. Use Instant) if you want to limit the time to night hours.") { c -> c.getTchilasZmanKidushLevana7Days() },
        ZmanMethod("sof-zman-achilas-chametz-gra", "chametz", "Chametz eating deadline Vilna Gaon", false, false, false, true, false, explicitElevation = false, sourceMethod = "getSofZmanAchilasChametzGRA", hebrewLabel = "סוף זמן אכילת חמץ הגר״א", definition = "4 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. Applies only on 14 Nisan (Erev Pesach). Day: Sunrise (profile elevation policy) → Sunset (profile elevation policy)", sourceDefinition = "This method returns the latest time one is allowed eating chametz on Erev Pesach according to the opinion of the GRA . This time is identical to the getSofZmanTfilaGRA() Sof zman tfilah GRA and is provided as a convenience method for those who are unaware how this zman is calculated. This time is 4 hours into the day based on the opinion of the GRA that the day is calculated from sunrise to sunset. This returns the time 4 getShaahZmanisGRA() after sea level sunrise. If it is not erev Pesach , a null will be returned.") { c -> c.getSofZmanAchilasChametzGRA() },
        ZmanMethod("sof-zman-achilas-chametz-mga72-minutes", "chametz", "Chametz eating deadline Magen Avraham 72 minutes", false, false, false, true, false, explicitElevation = false, sourceMethod = "getSofZmanAchilasChametzMGA72Minutes", hebrewLabel = "סוף זמן אכילת חמץ מגן אברהם 72 minutes", definition = "4 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. Applies only on 14 Nisan (Erev Pesach). Day: Dawn 72 minutes → Nightfall 72 minutes", sourceDefinition = "This method returns the latest time one is allowed eating chametz on Erev Pesach according to the opinion of the Magen Avraham (MGA) based on alos being 72 minutes before getSunrise(). This time is identical to the Sof zman tfilah MGA 72 minutes. This time is 4 getShaahZmanis72Minutes() shaos zmaniyos (temporal hours) after dawn based on the opinion of the MGA that the day is calculated from a dawn of 72 minutes before sunrise to getTzais72Minutes() nightfall of 72 minutes after sunset. This returns the time of 4 getShaahZmanis72Minutes() after dawn. If it is not erev Pesach , a null will be returned.") { c -> c.getSofZmanAchilasChametzMGA72Minutes() },
        ZmanMethod("sof-zman-achilas-chametz-mga72-minutes-zmanis", "chametz", "Chametz eating deadline Magen Avraham 72 temporal minutes", false, false, false, true, false, explicitElevation = false, sourceMethod = "getSofZmanAchilasChametzMGA72MinutesZmanis", hebrewLabel = "סוף זמן אכילת חמץ מגן אברהם 72 temporal minutes", definition = "4 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. Applies only on 14 Nisan (Erev Pesach). Day: Dawn 72 temporal minutes → Nightfall 72 temporal minutes", sourceDefinition = "This method returns the latest time one is allowed eating chametz on Erev Pesach according to the opinion of the Magen Avraham (MGA) based on alos being getAlos72Zmanis() 72 zmaniyos minutes before getSunrise(). This time is identical to the Sof zman tfilah MGA 72 minutes zmanis. This time is 4 getShaahZmanis72MinutesZmanis() shaos zmaniyos (temporal hours) after dawn based on the opinion of the MGA that the day is calculated from a dawn of 72 minutes zmanis before sunrise to nightfall of 72 minutes zmanis after sunset. This returns the time of 4 getShaahZmanis72MinutesZmanis() after dawn. If it is not erev Pesach , a null will be returned.") { c -> c.getSofZmanAchilasChametzMGA72MinutesZmanis() },
        ZmanMethod("sof-zman-achilas-chametz-mga16-point1-degrees", "chametz", "Chametz eating deadline Magen Avraham 16.1\u00b0 below horizon", false, false, false, false, false, explicitElevation = false, sourceMethod = "getSofZmanAchilasChametzMGA16Point1Degrees", hebrewLabel = "סוף זמן אכילת חמץ מגן אברהם 16.1° below the horizon", definition = "4 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. Applies only on 14 Nisan (Erev Pesach). Day: Dawn 16.1° below horizon → Nightfall 16.1° below horizon", sourceDefinition = "This method returns the latest time one is allowed eating chametz on Erev Pesach according to the opinion of the Magen Avraham (MGA) based on alos being getAlos16Point1Degrees() 16.1° before getSunrise(). This time is 4 getShaahZmanis16Point1Degrees() after getAlos16Point1Degrees() based on the opinion of the MGA that the day is calculated from dawn to nightfall with both being 16.1° below sunrise or sunset. This returns the time of 4 getShaahZmanis16Point1Degrees() after getAlos16Point1Degrees() dawn. If it is not erev Pesach , a null will be returned.") { c -> c.getSofZmanAchilasChametzMGA16Point1Degrees() },
        ZmanMethod("sof-zman-biur-chametz-gra", "chametz", "Chametz disposal deadline Vilna Gaon", false, false, false, true, false, explicitElevation = false, sourceMethod = "getSofZmanBiurChametzGRA", hebrewLabel = "סוף זמן ביעור חמץ הגר״א", definition = "5 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. Applies only on 14 Nisan (Erev Pesach). Day: Sunrise (profile elevation policy) → Sunset (profile elevation policy)", sourceDefinition = "This method returns the latest time for burning chametz on Erev Pesach according to the opinion of the GRA . This returns the time 5 getShaahZmanisGRA() after getSeaLevelSunrise(). If it is not erev Pesach , a null will be returned.") { c -> c.getSofZmanBiurChametzGRA() },
        ZmanMethod("sof-zman-biur-chametz-mga72-minutes", "chametz", "Chametz disposal deadline Magen Avraham 72 minutes", false, false, false, true, false, explicitElevation = false, sourceMethod = "getSofZmanBiurChametzMGA72Minutes", hebrewLabel = "סוף זמן ביעור חמץ מגן אברהם 72 minutes", definition = "5 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. Applies only on 14 Nisan (Erev Pesach). Day: Dawn 72 minutes → Nightfall 72 minutes", sourceDefinition = "This method returns the latest time for burning chametz on Erev Pesach according to the opinion of the Magen Avraham (MGA) based on alos being getAlos72Minutes() 72 minutes before getSunrise(). This time is 5 getShaahZmanis72Minutes() shaos zmaniyos (temporal hours) after dawn based on the opinion of the MGA that the day is calculated from a dawn of 72 minutes before sunrise to getTzais72Minutes() nightfall of 72 minutes after sunset. This returns the time of 5 getShaahZmanis72Minutes() after dawn. If it is not erev Pesach , a null will be returned.") { c -> c.getSofZmanBiurChametzMGA72Minutes() },
        ZmanMethod("sof-zman-biur-chametz-mga72-minutes-zmanis", "chametz", "Chametz disposal deadline Magen Avraham 72 temporal minutes", false, false, false, true, false, explicitElevation = false, sourceMethod = "getSofZmanBiurChametzMGA72MinutesZmanis", hebrewLabel = "סוף זמן ביעור חמץ מגן אברהם 72 temporal minutes", definition = "5 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. Applies only on 14 Nisan (Erev Pesach). Day: Dawn 72 temporal minutes → Nightfall 72 temporal minutes", sourceDefinition = "This method returns the latest time for burning chametz on Erev Pesach according to the opinion of the Magen Avraham (MGA) based on alos being getAlos72Zmanis() 72 minutes zmanis before getSunrise(). This time is 5 getShaahZmanis72MinutesZmanis() shaos zmaniyos (temporal hours) after dawn based on the opinion of the MGA that the day is calculated from a dawn of 72 minutes zmanis before sunrise to nightfall of 72 minutes zmanis after sunset. This returns the time of 5 getShaahZmanis72MinutesZmanis() after dawn. If it is not erev Pesach , a null will be returned.") { c -> c.getSofZmanBiurChametzMGA72MinutesZmanis() },
        ZmanMethod("sof-zman-biur-chametz-mga16-point1-degrees", "chametz", "Chametz disposal deadline Magen Avraham 16.1\u00b0 below horizon", false, false, false, false, false, explicitElevation = false, sourceMethod = "getSofZmanBiurChametzMGA16Point1Degrees", hebrewLabel = "סוף זמן ביעור חמץ מגן אברהם 16.1° below the horizon", definition = "5 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. Applies only on 14 Nisan (Erev Pesach). Day: Dawn 16.1° below horizon → Nightfall 16.1° below horizon", sourceDefinition = "This method returns the latest time for burning chametz on Erev Pesach according to the opinion of the Magen Avraham (MGA) based on alos being 16.1° before getSunrise(). This time is 5 shaos zmaniyos (solar hours) after dawn based on the opinion of the MGA that the day is calculated from dawn to nightfall with both being 16.1° below sunrise or sunset. This returns the time of 5 getShaahZmanis16Point1Degrees() after dawn. If it is not erev Pesach , a null will be returned.") { c -> c.getSofZmanBiurChametzMGA16Point1Degrees() },
        ZmanMethod("shaah-zmanis-baal-hatanya", "duration", "Temporal hour Baal Ha Tanya \u00b7 Day: Sunrise Baal Ha Tanya \u2192 Sunset Baal Ha Tanya", true, false, false, false, false, explicitElevation = false, sourceMethod = "getShaahZmanisBaalHatanya", hebrewLabel = "שעה זמנית בעל התניא", definition = "One twelfth of the specified day interval; a duration rather than a clock time. Baal HaTanya boundaries use the sun at 1.583° below the sea-level horizon, not the location height. Day: Sunrise Baal Ha Tanya → Sunset Baal Ha Tanya", sourceDefinition = "A method that returns the Baal Hatanya 's a shaah zmanis (Instant) temporal hour). This forms the base for the Baal Hatanya's day based calculations that are calculated as a 1.583° dip below the horizon after sunset. According to the Baal Hatanya, shkiah amiti , true (halachic) sunset, is when the top of the sun's disk disappears from view at an elevation similar to the mountains of Eretz Yisrael. This time is calculated as the point at which the center of the sun's disk is 1.583° below the horizon. A method that returns a shaah zmanis (Instant) temporal hour) calculated based on the Baal Hatanya 's netz amiti and shkiah amiti using a dip of 1.583° below the sea level horizon. This calculation divides the day based on the opinion of the Baal Hatanya that the day runs from netz amiti to shkiah amiti . The calculations are based on a day from sea level netz amiti to sea level shkiah amiti . The day is split into 12 equal parts with each one being a shaah zmanis . This method is similar to getTemporalHour, but all calculations are based on a sea level sunrise and sunset.") { c -> c.getShaahZmanisBaalHatanya() },
        ZmanMethod("alos-baal-hatanya", "dawn", "Dawn Baal Ha Tanya", false, false, false, false, false, explicitElevation = false, sourceMethod = "getAlosBaalHatanya", hebrewLabel = "עלות השחר בעל התניא", definition = "Morning solar depression of 16.9° below the geometric horizon. This is a solar angle, not a fixed 72-minute offset.", sourceDefinition = "Returns the Baal Hatanya 's alos (dawn) calculated as the time when the sun is 16.9° below the eastern geometric horizon before getSunrise(). It is based on the calculation that the time between dawn and netz amiti (sunrise) is 72 minutes, the time that is takes to walk 4 mil at 18 minutes a mil ( Rambam and others). The sun's position at 72 minutes before netz amiti (sunrise) in Jerusalem around the equinox / equilux is 16.9° below GEOMETRIC_ZENITH.") { c -> c.getAlosBaalHatanya() },
        ZmanMethod("sof-zman-shma-baal-hatanya", "shema", "Latest Shema Baal Ha Tanya \u00b7 Day: Sunrise Baal Ha Tanya \u2192 Sunset Baal Ha Tanya", false, false, false, false, true, explicitElevation = false, sourceMethod = "getSofZmanShmaBaalHatanya", hebrewLabel = "סוף זמן קריאת שמע בעל התניא", definition = "3 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. Baal HaTanya boundaries use the sun at 1.583° below the sea-level horizon, not the location height. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Sunrise Baal Ha Tanya → Sunset Baal Ha Tanya", sourceDefinition = "This method returns the latest zman krias shema (time to recite Shema in the morning). This time is 3 getShaahZmanisBaalHatanya() shaos zmaniyos (solar hours) after netz amiti (sunrise) based on the opinion of the Baal Hatanya that the day is calculated from sunrise to sunset. This returns the time 3 getShaahZmanisBaalHatanya() after netz amiti (sunrise).") { c -> c.getSofZmanShmaBaalHatanya() },
        ZmanMethod("sof-zman-tfila-baal-hatanya", "prayer", "Latest teffilah Baal Ha Tanya \u00b7 Day: Sunrise Baal Ha Tanya \u2192 Sunset Baal Ha Tanya", false, false, false, false, true, explicitElevation = false, sourceMethod = "getSofZmanTfilaBaalHatanya", hebrewLabel = "סוף זמן תפילה בעל התניא", definition = "4 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. Baal HaTanya boundaries use the sun at 1.583° below the sea-level horizon, not the location height. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Sunrise Baal Ha Tanya → Sunset Baal Ha Tanya", sourceDefinition = "This method returns the latest zman tfilah (time to recite the morning prayers). This time is 4 hours into the day based on the opinion of the Baal Hatanya that the day is calculated from sunrise to sunset. This returns the time 4 getShaahZmanisBaalHatanya() after netz amiti (sunrise).") { c -> c.getSofZmanTfilaBaalHatanya() },
        ZmanMethod("sof-zman-achilas-chametz-baal-hatanya", "chametz", "Chametz eating deadline Baal Ha Tanya", false, false, false, false, false, explicitElevation = false, sourceMethod = "getSofZmanAchilasChametzBaalHatanya", hebrewLabel = "סוף זמן אכילת חמץ בעל התניא", definition = "4 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. Applies only on 14 Nisan (Erev Pesach). Baal HaTanya boundaries use the sun at 1.583° below the sea-level horizon, not the location height. Day: Sunrise Baal Ha Tanya → Sunset Baal Ha Tanya", sourceDefinition = "This method returns the latest time one is allowed eating chametz on Erev Pesach according to the opinion of the Baal Hatanya. This time is identical to the Sof zman tfilah Baal Hatanya. This time is 4 hours into the day based on the opinion of the Baal Hatanya that the day is calculated from sunrise to sunset. This returns the time 4 getShaahZmanisBaalHatanya() after netz amiti (sunrise). If it is not erev Pesach , a null will be returned.") { c -> c.getSofZmanAchilasChametzBaalHatanya() },
        ZmanMethod("sof-zman-biur-chametz-baal-hatanya", "chametz", "Chametz disposal deadline Baal Ha Tanya", false, false, false, false, false, explicitElevation = false, sourceMethod = "getSofZmanBiurChametzBaalHatanya", hebrewLabel = "סוף זמן ביעור חמץ בעל התניא", definition = "5 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. Applies only on 14 Nisan (Erev Pesach). Baal HaTanya boundaries use the sun at 1.583° below the sea-level horizon, not the location height. Day: Sunrise Baal Ha Tanya → Sunset Baal Ha Tanya", sourceDefinition = "This method returns the latest time for burning chametz on Erev Pesach according to the opinion of the Baal Hatanya. This time is 5 hours into the day based on the opinion of the Baal Hatanya that the day is calculated from sunrise to sunset. This returns the time 5 getShaahZmanisBaalHatanya() after netz amiti (sunrise). If it is not erev Pesach , a null will be returned.") { c -> c.getSofZmanBiurChametzBaalHatanya() },
        ZmanMethod("mincha-gedola-baal-hatanya", "mincha-gedolah", "Earliest Mincha Baal Ha Tanya \u00b7 Day: Sunrise Baal Ha Tanya \u2192 Sunset Baal Ha Tanya", false, false, false, false, true, explicitElevation = false, sourceMethod = "getMinchaGedolaBaalHatanya", hebrewLabel = "מנחה גדולה בעל התניא", definition = "6.5 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. Baal HaTanya boundaries use the sun at 1.583° below the sea-level horizon, not the location height. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Sunrise Baal Ha Tanya → Sunset Baal Ha Tanya", sourceDefinition = "This method returns the time of mincha gedola . Mincha gedola is the earliest time one can pray mincha . The Rambam is of the opinion that it is better to delay mincha until mincha ketana while the Ra\"sh , Tur , GRA and others are of the opinion that mincha can be prayed lechatchila starting at mincha gedola . This is calculated as 6.5 sea level solar hours after netz amiti (sunrise). This calculation is based on the opinion of the Baal Hatanya that the day is calculated from sunrise to sunset. This returns the time 6.5 getShaahZmanisBaalHatanya() after netz amiti (\"real\" sunrise). @todo Consider adjusting this to calculate the time as 30 clock or zmaniyos minutes after either getSunTransit() astronomical chatzos or chatzos as half a day for calculators that support it, based on isUseAstronomicalChatzos().") { c -> c.getMinchaGedolaBaalHatanya() },
        ZmanMethod("mincha-ketana-baal-hatanya", "mincha-ketanah", "Mincha ketanah Baal Ha Tanya \u00b7 Day: Sunrise Baal Ha Tanya \u2192 Sunset Baal Ha Tanya", false, false, false, false, true, explicitElevation = false, sourceMethod = "getMinchaKetanaBaalHatanya", hebrewLabel = "מנחה קטנה בעל התניא", definition = "9.5 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. Baal HaTanya boundaries use the sun at 1.583° below the sea-level horizon, not the location height. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Sunrise Baal Ha Tanya → Sunset Baal Ha Tanya", sourceDefinition = "This method returns the time of mincha ketana . This is the preferred earliest time to pray mincha in the opinion of the Rambam and others. For more information on this see the documentation on mincha gedola . This is calculated as 9.5 getShaahZmanisBaalHatanya() sea level solar hours after netz amiti (sunrise). This calculation is calculated based on the opinion of the Baal Hatanya that the day is calculated from sunrise to sunset. This returns the time 9.5 getShaahZmanisBaalHatanya() after netz amiti .") { c -> c.getMinchaKetanaBaalHatanya() },
        ZmanMethod("plag-hamincha-baal-hatanya", "plag", "Plag Baal Ha Tanya \u00b7 Day: Sunrise Baal Ha Tanya \u2192 Sunset Baal Ha Tanya", false, false, false, false, true, explicitElevation = false, sourceMethod = "getPlagHaminchaBaalHatanya", hebrewLabel = "פלג המנחה בעל התניא", definition = "10.75 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. Baal HaTanya boundaries use the sun at 1.583° below the sea-level horizon, not the location height. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Sunrise Baal Ha Tanya → Sunset Baal Ha Tanya", sourceDefinition = "This method returns the time of plag hamincha . This is calculated as 10.75 hours after sunrise. This calculation is based on the opinion of the Baal Hatanya that the day is calculated from sunrise to sunset. This returns the time 10.75 getShaahZmanisBaalHatanya() after netz amiti (sunrise). See About Our Zmanim Calculations @ Chabad.org for more details on this calculation.") { c -> c.getPlagHaminchaBaalHatanya() },
        ZmanMethod("tzais-baal-hatanya", "nightfall", "Nightfall Baal Ha Tanya", false, false, false, false, false, explicitElevation = false, sourceMethod = "getTzaisBaalHatanya", hebrewLabel = "צאת הכוכבים בעל התניא", definition = "Evening solar depression of 6° below the geometric horizon. This is a solar angle, not a fixed-minute offset.", sourceDefinition = "A method that returns tzais (nightfall) when the sun is 6° below the western geometric horizon (90°) after getSunset() sunset. This tzais / nightfall based on the opinion of the Baal Hatanya . This calculation is based on the position of the sun about 24 minutes after sunset in Jerusalem around the equinox / equilux , which is 6° below GEOMETRIC_ZENITH. See About Our Zmanim Calculations @ Chabad.org that is based on shkiah amitis as 1.583° below the horizon calculated around the equinox / equilux that computes 3.516 minutes after sunset. To this, 18 minutes of 3/4 of a 24-minute mil and two minutes for bain hashmashos of Rav Yosi is added. This calculation computes the sun being 5.83° below the horizon (very close to the slightly later getTzaisGeonim5Point95Degrees() that was calculated based on 4 fixed minutes) and it is rounded up to 6°.") { c -> c.getTzaisBaalHatanya() },
        ZmanMethod("sof-zman-shma-mga18-degrees-to-fixed-local-chatzos", "shema", "Latest Shema Magen Avraham 18\u00b0 below horizon To Fixed local Chatzos \u00b7 Day: Dawn 18\u00b0 below horizon \u2192 Fixed local Midday", false, false, false, false, false, explicitElevation = false, sourceMethod = "getSofZmanShmaMGA18DegreesToFixedLocalChatzos", hebrewLabel = "סוף זמן קריאת שמע מגן אברהם 18° below the horizon To Fixed local Chatzos", definition = "3 sixths of the specified half-day after its start. This method explicitly uses fixed local noon and does not follow the profile’s optional half-day switch. Day: Dawn 18° below horizon → Fixed local Midday", sourceDefinition = "This method returns Rav Moshe Feinstein's opinion of the calculation of sof zman krias shema (latest time to recite Shema in the morning) according to the opinion of the Magen Avraham (MGA) that the day is calculated from dawn to nightfall, but calculated using the first half of the day only. The half a day starts at alos defined as 18° and ends at fixed local chatzos. Sof Zman Shema is 3 shaos zmaniyos (solar hours) after alos or half of this half-day.") { c -> c.getSofZmanShmaMGA18DegreesToFixedLocalChatzos() },
        ZmanMethod("sof-zman-shma-mga16-point1-degrees-to-fixed-local-chatzos", "shema", "Latest Shema Magen Avraham 16.1\u00b0 below horizon To Fixed local Chatzos \u00b7 Day: Dawn 16.1\u00b0 below horizon \u2192 Fixed local Midday", false, false, false, false, false, explicitElevation = false, sourceMethod = "getSofZmanShmaMGA16Point1DegreesToFixedLocalChatzos", hebrewLabel = "סוף זמן קריאת שמע מגן אברהם 16.1° below the horizon To Fixed local Chatzos", definition = "3 sixths of the specified half-day after its start. This method explicitly uses fixed local noon and does not follow the profile’s optional half-day switch. Day: Dawn 16.1° below horizon → Fixed local Midday", sourceDefinition = "This method returns Rav Moshe Feinstein's opinion of the calculation of sof zman krias shema (latest time to recite Shema in the morning) according to the opinion of the Magen Avraham (MGA) that the day is calculated from dawn to nightfall, but calculated using the first half of the day only. The half a day starts at alos defined as 16.1° and ends at fixed local chatzos. Sof Zman Shema is 3 shaos zmaniyos (solar hours) after this alos or half of this half-day.") { c -> c.getSofZmanShmaMGA16Point1DegreesToFixedLocalChatzos() },
        ZmanMethod("sof-zman-shma-mga90-minutes-to-fixed-local-chatzos", "shema", "Latest Shema Magen Avraham 90 minutes To Fixed local Chatzos \u00b7 Day: Dawn 90 minutes \u2192 Fixed local Midday", false, false, false, true, false, explicitElevation = false, sourceMethod = "getSofZmanShmaMGA90MinutesToFixedLocalChatzos", hebrewLabel = "סוף זמן קריאת שמע מגן אברהם 90 minutes To Fixed local Chatzos", definition = "3 sixths of the specified half-day after its start. This method explicitly uses fixed local noon and does not follow the profile’s optional half-day switch. Day: Dawn 90 minutes → Fixed local Midday", sourceDefinition = "This method returns Rav Moshe Feinstein's opinion of the calculation of sof zman krias shema (latest time to recite Shema in the morning) according to the opinion of the Magen Avraham (MGA) that the day is calculated from dawn to nightfall, but calculated using the first half of the day only. The half a day starts at alos defined as getAlos90Minutes() 90 minutes before sunrise and ends at fixed local chatzos. Sof Zman Shema is 3 shaos zmaniyos (solar hours) after this alos or half of this half-day.") { c -> c.getSofZmanShmaMGA90MinutesToFixedLocalChatzos() },
        ZmanMethod("sof-zman-shma-mga72-minutes-to-fixed-local-chatzos", "shema", "Latest Shema Magen Avraham 72 minutes To Fixed local Chatzos \u00b7 Day: Dawn 72 minutes \u2192 Fixed local Midday", false, false, false, true, false, explicitElevation = false, sourceMethod = "getSofZmanShmaMGA72MinutesToFixedLocalChatzos", hebrewLabel = "סוף זמן קריאת שמע מגן אברהם 72 minutes To Fixed local Chatzos", definition = "3 sixths of the specified half-day after its start. This method explicitly uses fixed local noon and does not follow the profile’s optional half-day switch. Day: Dawn 72 minutes → Fixed local Midday", sourceDefinition = "This method returns Rav Moshe Feinstein's opinion of the calculation of sof zman krias shema (latest time to recite Shema in the morning) according to the opinion of the Magen Avraham (MGA) that the day is calculated from dawn to nightfall, but calculated using the first half of the day only. The half a day starts at alos defined as getAlos72Minutes() 72 minutes before sunrise and ends at getFixedLocalChatzosHayom(). Sof Zman Shema is 3 shaos zmaniyos (solar hours) after this alos or half of this half-day.") { c -> c.getSofZmanShmaMGA72MinutesToFixedLocalChatzos() },
        ZmanMethod("sof-zman-shma-grasunrise-to-fixed-local-chatzos", "shema", "Latest Shema Vilna Gaon Sunrise To Fixed local Chatzos \u00b7 Day: Sunrise (profile elevation policy) \u2192 Fixed local Midday", false, false, false, true, false, explicitElevation = false, sourceMethod = "getSofZmanShmaGRASunriseToFixedLocalChatzos", hebrewLabel = "סוף זמן קריאת שמע הגר״א הנץ החמה To Fixed local Chatzos", definition = "3 sixths of the specified half-day after its start. This method explicitly uses fixed local noon and does not follow the profile’s optional half-day switch. Day: Sunrise (profile elevation policy) → Fixed local Midday", sourceDefinition = "This method returns Rav Moshe Feinstein's opinion of the calculation of sof zman krias shema (latest time to recite Shema in the morning) according to the opinion of the GRA that the day is calculated from sunrise to sunset, but calculated using the first half of the day only. The half a day starts at getSunrise() and ends at fixed local chatzos. Sof zman Shema is 3 shaos zmaniyos (solar hours) after sunrise or half of this half-day.") { c -> c.getSofZmanShmaGRASunriseToFixedLocalChatzos() },
        ZmanMethod("sof-zman-tfila-grasunrise-to-fixed-local-chatzos", "prayer", "Latest teffilah Vilna Gaon Sunrise To Fixed local Chatzos \u00b7 Day: Sunrise (profile elevation policy) \u2192 Fixed local Midday", false, false, false, true, false, explicitElevation = false, sourceMethod = "getSofZmanTfilaGRASunriseToFixedLocalChatzos", hebrewLabel = "סוף זמן תפילה הגר״א הנץ החמה To Fixed local Chatzos", definition = "4 sixths of the specified half-day after its start. This method explicitly uses fixed local noon and does not follow the profile’s optional half-day switch. Day: Sunrise (profile elevation policy) → Fixed local Midday", sourceDefinition = "This method returns Rav Moshe Feinstein's opinion of the calculation of sof zman tfila ( zman tfilah (the latest time to recite the morning prayers)) according to the opinion of the GRA that the day is calculated from sunrise to sunset, but calculated using the first half of the day only. The half a day starts at getSunrise() and ends at fixed local chatzos. Sof zman tefila is 4 shaos zmaniyos (solar hours) after sunrise or 2/3 of this half-day.") { c -> c.getSofZmanTfilaGRASunriseToFixedLocalChatzos() },
        ZmanMethod("mincha-gedola-grafixed-local-chatzos30-minutes", "mincha-gedolah", "Earliest Mincha Vilna Gaon Fixed local Chatzos 30 minutes", false, false, false, false, false, explicitElevation = false, sourceMethod = "getMinchaGedolaGRAFixedLocalChatzos30Minutes", hebrewLabel = "מנחה גדולה הגר״א Fixed local Chatzos 30 minutes", definition = "Thirty fixed clock minutes after longitude-based fixed local noon, independent of sunrise and sunset.", sourceDefinition = "This method returns Rav Moshe Feinstein's opinion of the calculation of mincha gedola , the earliest time one can pray mincha according to the GRA calculated as 30 minutes after fixed local chatzos.") { c -> c.getMinchaGedolaGRAFixedLocalChatzos30Minutes() },
        ZmanMethod("mincha-ketana-grafixed-local-chatzos-to-sunset", "mincha-ketanah", "Mincha ketanah Vilna Gaon Fixed local Chatzos To Sunset \u00b7 Day: Fixed local Midday \u2192 Sunset (profile elevation policy)", false, false, false, true, false, explicitElevation = false, sourceMethod = "getMinchaKetanaGRAFixedLocalChatzosToSunset", hebrewLabel = "מנחה קטנה הגר״א Fixed local Chatzos To שקיעה", definition = "3.5 sixths of the specified half-day after its start. This method explicitly uses fixed local noon and does not follow the profile’s optional half-day switch. Day: Fixed local Midday → Sunset (profile elevation policy)", sourceDefinition = "This method returns Rav Moshe Feinstein's opinion of the calculation of mincha ketana (the preferred time to recite the mincha prayers according to the opinion of the Rambam and others) calculated according to the GRA that is 3.5 shaos zmaniyos (solar hours) after fixed local chatzos.") { c -> c.getMinchaKetanaGRAFixedLocalChatzosToSunset() },
        ZmanMethod("plag-hamincha-grafixed-local-chatzos-to-sunset", "plag", "Plag Vilna Gaon Fixed local Chatzos To Sunset \u00b7 Day: Fixed local Midday \u2192 Sunset (profile elevation policy)", false, false, false, true, false, explicitElevation = false, sourceMethod = "getPlagHaminchaGRAFixedLocalChatzosToSunset", hebrewLabel = "פלג המנחה הגר״א Fixed local Chatzos To שקיעה", definition = "4.75 sixths of the specified half-day after its start. This method explicitly uses fixed local noon and does not follow the profile’s optional half-day switch. Day: Fixed local Midday → Sunset (profile elevation policy)", sourceDefinition = "This method returns Rav Moshe Feinstein's opinion of the calculation of plag hamincha . This method returns plag hamincha calculated according to the GRA that the day ends at sunset and is 4.75 shaos zmaniyos (solar hours) after fixed local chatzos.") { c -> c.getPlagHaminchaGRAFixedLocalChatzosToSunset() },
        ZmanMethod("tzais50-minutes", "nightfall", "Nightfall 50 minutes", false, false, false, true, false, explicitElevation = false, sourceMethod = "getTzais50Minutes", hebrewLabel = "צאת הכוכבים 50 minutes", definition = "50 fixed clock minutes after sunset. Sunrise/sunset follow the profile elevation policy.", sourceDefinition = "Method to return tzais (dusk) calculated as 50 minutes after sunset or getSeaLevelSunset() sea level sunset (depending on the isUseElevation() setting). This method returns tzais (nightfall) based on the opinion of Rabbi Moshe Feinstein for the New York area. This time should not be used for latitudes other than ones similar to the latitude of the NY area.") { c -> c.getTzais50Minutes() },
        ZmanMethod("samuch-le-mincha-ketana-gra", "mincha-ketanah", "Before Mincha ketanah Vilna Gaon \u00b7 Day: Sunrise (profile elevation policy) \u2192 Sunset (profile elevation policy)", false, false, false, true, true, explicitElevation = false, sourceMethod = "getSamuchLeMinchaKetanaGRA", hebrewLabel = "Before מנחה קטנה הגר״א", definition = "9 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Sunrise (profile elevation policy) → Sunset (profile elevation policy)", sourceDefinition = "A method for calculating samuch lemincha ketana , / near mincha ketana time that is half an hour before getMinchaKetanaGRA() or is 9 shaos zmaniyos (solar hours) after the start of the day, calculated according to the GRA using a day starting at sunrise and ending at sunset. This is the time that eating or other activity can't begin prior to praying mincha . The calculation used is 9 getShaahZmanisGRA() after getSunrise() or getSunriseBasedOnElevationSetting() elevation adjusted sunrise (depending on the isUseElevation() setting). See the Mechaber and Mishna Berurah 232 and 249:2 .") { c -> c.getSamuchLeMinchaKetanaGRA() },
        ZmanMethod("samuch-le-mincha-ketana16-point1-degrees", "mincha-ketanah", "Before Mincha ketanah 16.1\u00b0 below horizon \u00b7 Day: Dawn 16.1\u00b0 below horizon \u2192 Nightfall 16.1\u00b0 below horizon", false, false, false, false, true, explicitElevation = false, sourceMethod = "getSamuchLeMinchaKetana16Point1Degrees", hebrewLabel = "Before מנחה קטנה 16.1° below the horizon", definition = "9 temporal hours after the specified day begins. A full-day temporal hour is one twelfth of that interval. When enabled, the library’s supported half-day policy uses six morning/afternoon hours around the profile chatzos. Day: Dawn 16.1° below horizon → Nightfall 16.1° below horizon", sourceDefinition = "A method for calculating samuch lemincha ketana , / near mincha ketana time that is half an hour before getMinchaKetanaGRA() or is 9 shaos zmaniyos (solar hours) after the start of the day, calculated based on a day from and ending a day starting at alos 16.1° and ending at tzais 16.1°. This is the time that eating or other activity can't begin prior to praying mincha . The calculation used is 9 getShaahZmanis16Point1Degrees() after getAlos16Point1Degrees() alos 16.1°. See the Mechaber and Mishna Berurah 232 and 249:2 .") { c -> c.getSamuchLeMinchaKetana16Point1Degrees() },
