        ZmanMethod("polar-sunset-ben-ish-chai", "sunset", "Polar Sunset Ben Ish Chai", false, false, false, true, false, explicitElevation = false, sourceMethod = "getPolarSunsetBenIshChai", hebrewLabel = "Polar שקיעה בן איש חי", definition = "When ordinary sunset is absent, uses the sun’s due-west azimuth of 270°. Does not apply on dates with ordinary sunset.", sourceDefinition = "A method that returns sunset calculated as the time when the sun is directly due west (azimuth 270°) in Polar regions on days that there are no getSunsetBasedOnElevationSetting() sunset. If there is sunset that day, a null will be returned. In Polar regions (the Arctic or Antarctic circles), there are days of no sunrise or sunset, and there are halachic opinions that during these periods, sunset (the day-night boundary) is reached when the sun is directly due west (azimuth 270°). Sunrise in this opinion is when the sun is directly due east (azimuth 90°) returned by getPolarSunriseBenIshChai(). This is the opinion of Rabbi Yehosef Schwarz in his דברי יוסף – דרך מבוא השמש and דברי יוסף – תשובות, שאלה ח׳ . This is brought down lehalacha by The Ben Ish Chai in the רב פעלים – חלק ב׳, סוד ישרים ס׳ ד׳ . This time is close to six hours after astronomical chatzos hayom , but depending on the time of year and location in the Arctic / Antarctic, it can be up to 46 minutes before or after this time.") { c -> c.getPolarSunsetBenIshChai() },
        ZmanMethod("polar-sunrise-ben-ish-chai", "sunrise", "Polar Sunrise Ben Ish Chai", false, false, false, true, false, explicitElevation = false, sourceMethod = "getPolarSunriseBenIshChai", hebrewLabel = "Polar הנץ החמה בן איש חי", definition = "When ordinary sunrise is absent, uses the sun’s due-east azimuth of 90°. Does not apply on dates with ordinary sunrise.", sourceDefinition = "A method that returns sunrise calculated as the time when the sun is directly due east (azimuth 90°) in Polar regions on days that there are no getSunriseBasedOnElevationSetting() sunrise. If there is sunrise that day, a null will be returned. In Polar regions (the Arctic or Antarctic circles), there are days of no sunrise or sunset, and there are halachic opinions that during these periods, sunrise is reached when the sun is directly due east (azimuth 90°). The day-night boundary (sunset) in these opinions is when the sun is directly due west (azimuth 270°) returned by getPolarSunsetBenIshChai(). This is the opinion of Rabbi Yehosef Schwarz in his דברי יוסף – דרך מבוא השמש and דברי יוסף – תשובות, שאלה ח׳ . This is brought down lehalacha by The Ben Ish Chai in the רב פעלים – חלק ב׳, סוד ישרים ס׳ ד׳ . This time is close to six hours before astronomical chatzos hayom , but depending on the time of year and location in the Arctic / Antarctic, it can be up to 46 minutes before or after this time.") { c -> c.getPolarSunriseBenIshChai() },
